window.LEVEL_DATA["A2"] = {"ai-02":{"intro":"Kuruluş hikayeni anlatmak: sorun, fikir ve misyon.","text":[{"en":"Around the world, more than one billion people have some hearing loss.","tr":"Dünya genelinde bir milyardan fazla insanın bir miktar işitme kaybı var."},{"en":"Many of them never get a hearing test because there are not enough experts.","tr":"Birçoğu hiç işitme testi yaptırmıyor, çünkü yeterli uzman yok."},{"en":"In small towns, people sometimes wait months for an appointment.","tr":"Küçük kasabalarda insanlar bazen randevu için aylarca bekliyor."},{"en":"We saw this problem and asked a simple question.","tr":"Bu sorunu gördük ve basit bir soru sorduk."},{"en":"What if a machine could do the test without an expert?","tr":"Ya bir makine testi uzman olmadan yapabilseydi?"},{"en":"That question became AIHEAR.","tr":"O soru AIHEAR'a dönüştü."},{"en":"Our mission is to make hearing tests accessible to everyone, everywhere.","tr":"Misyonumuz işitme testlerini herkes için, her yerde erişilebilir kılmak."},{"en":"We started in Turkey, but the problem is global, so our market is too.","tr":"Türkiye'de başladık ama sorun küresel, bu yüzden pazarımız da öyle."}],"vocab":[{"en":"hearing loss","tr":"işitme kaybı","ex":"Many people have hearing loss."},{"en":"appointment","tr":"randevu","ex":"People wait months for an appointment."},{"en":"What if...?","tr":"Ya ... olsaydı?","ex":"What if a machine could do the test?"},{"en":"mission","tr":"misyon, amaç","ex":"Our mission is to help people hear."},{"en":"accessible","tr":"erişilebilir","ex":"We want to make hearing tests accessible."},{"en":"everyone, everywhere","tr":"herkes, her yerde","ex":"Hearing tests should be for everyone, everywhere."},{"en":"global","tr":"küresel","ex":"The problem is global."},{"en":"market","tr":"pazar","ex":"Our market is global."}],"grammar":{"title":"Past simple: our story","tr":"Geçmişte bitmiş olayları anlatırken past simple kullanılır. Düzenli fiiller -ed alır (asked, started), düzensiz fiiller değişir (see → saw, become → became).","examples":["We saw this problem.","We asked a simple question.","That question became AIHEAR."]},"questions":[{"q":"How many people have some hearing loss?","options":["One million","Ten thousand","More than one billion"],"a":2},{"q":"Why do many people never get a test?","options":["There are not enough experts","Tests are too easy","They don't want one"],"a":0},{"q":"What is AIHEAR's mission?","options":["To sell headphones","To make hearing tests accessible to everyone","To open hospitals"],"a":1},{"q":"Where did the company start?","options":["Germany","Turkey","The USA"],"a":1}],"gaps":[{"s":"People sometimes wait months for an ___.","a":"appointment","hint":"randevu"},{"s":"Our ___ is to make hearing tests accessible.","a":"mission","hint":"misyon"},{"s":"The problem is ___, so our market is too.","a":"global","hint":"küresel"}],"order":[{"a":"That question became AIHEAR."},{"a":"There are not enough experts."}],"translate":[{"tr":"Sorun küresel.","en":"The problem is global.","keys":["problem","global"]},{"tr":"Biz Türkiye'de başladık.","en":"We started in Turkey.","keys":["started","Turkey"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir teknoloji gazetecisi kısa bir röportaj için şirketin hikayesini soruyor.","turns":[{"ai":"Why did you start AIHEAR? What was the problem?","aiTr":"AIHEAR'ı neden kurdunuz? Sorun neydi?","hint":"More than one billion people have hearing loss, but there are not enough experts.","keys":["hearing loss","experts","not enough"]},{"ai":"So what was your idea?","aiTr":"Peki fikriniz neydi?","hint":"We asked: what if a machine could do the test without an expert?","keys":["what if","machine","without"]},{"ai":"What is your mission today?","aiTr":"Bugünkü misyonunuz ne?","hint":"Our mission is to make hearing tests accessible to everyone, everywhere.","keys":["mission","accessible","everyone"]}]}},"ai-01":{"intro":"Cihazını basit cümlelerle, adım adım anlatmak.","text":[{"en":"An audiometer is a device that measures how well a person can hear.","tr":"Odyometre, bir kişinin ne kadar iyi duyabildiğini ölçen bir cihazdır."},{"en":"A normal hearing test needs an expert, a quiet room and about thirty minutes.","tr":"Normal bir işitme testi için bir uzman, sessiz bir oda ve yaklaşık otuz dakika gerekir."},{"en":"Our audiometer is autonomous, so it can work by itself.","tr":"Bizim odyometremiz otonom, yani kendi kendine çalışabiliyor."},{"en":"The patient puts on the headphones and follows the instructions on the screen.","tr":"Hasta kulaklıkları takar ve ekrandaki talimatları takip eder."},{"en":"The device plays sounds at different volumes and frequencies.","tr":"Cihaz farklı ses seviyelerinde ve frekanslarda sesler çalar."},{"en":"When the patient hears a sound, they press a button.","tr":"Hasta bir ses duyduğunda bir düğmeye basar."},{"en":"Our AI checks the answers and changes the test in real time.","tr":"Yapay zekâmız cevapları kontrol eder ve testi gerçek zamanlı olarak değiştirir."},{"en":"At the end, the device creates a report called an audiogram.","tr":"Sonunda cihaz, odyogram adı verilen bir rapor oluşturur."},{"en":"It takes less than ten minutes, and no expert needs to be there.","tr":"Test on dakikadan kısa sürer ve orada bir uzmanın bulunması gerekmez."}],"vocab":[{"en":"measure","tr":"ölçmek","ex":"Our device measures how well people hear."},{"en":"autonomous","tr":"otonom, kendi kendine çalışan","ex":"Our audiometer is autonomous."},{"en":"put on the headphones","tr":"kulaklıkları takmak","ex":"The patient puts on the headphones."},{"en":"follow the instructions","tr":"talimatları takip etmek","ex":"Follow the instructions on the screen."},{"en":"frequency","tr":"frekans","ex":"It plays sounds at different frequencies."},{"en":"press a button","tr":"düğmeye basmak","ex":"When you hear a sound, press the button."},{"en":"in real time","tr":"gerçek zamanlı olarak","ex":"The AI changes the test in real time."},{"en":"audiogram","tr":"odyogram (işitme grafiği)","ex":"The device creates an audiogram."}],"grammar":{"title":"When + present simple: steps in a process","tr":"Bir süreçteki adımları anlatırken 'when' ile iki eylemi bağlarsın: biri olunca diğeri olur. İki tarafta da present simple kullanılır.","examples":["When the patient hears a sound, they press a button.","When the test ends, the device creates an audiogram."]},"questions":[{"q":"What does an audiometer measure?","options":["Blood pressure","Eyesight","How well a person can hear"],"a":2},{"q":"What does 'autonomous' mean here?","options":["It is very expensive","It can work by itself","It is very small"],"a":1},{"q":"What does the patient do when they hear a sound?","options":["Press a button","Say 'yes'","Raise a hand"],"a":0},{"q":"How long does a normal hearing test take?","options":["Less than ten minutes","Two hours","About thirty minutes"],"a":2}],"gaps":[{"s":"An audiometer ___ how well a person can hear.","a":"measures","hint":"ölçer"},{"s":"The patient puts on the ___ and follows the instructions.","a":"headphones","hint":"kulaklık"},{"s":"The AI changes the test in real ___.","a":"time","hint":"gerçek zamanlı"}],"order":[{"a":"Our audiometer can work by itself."},{"a":"It takes less than ten minutes."}],"translate":[{"tr":"Odada uzman gerekmez.","en":"No expert is needed in the room.","keys":["expert","room"]},{"tr":"Cihaz bir rapor oluşturur.","en":"The device creates a report.","keys":["device","report"]}],"roleplay":{"persona":"Curious doctor","personaTr":"Meraklı doktor","scene":"Bir fuarda, standına gelen İngiliz bir kulak burun boğaz doktoru cihazı soruyor.","turns":[{"ai":"What is this device? What does it do?","aiTr":"Bu cihaz ne? Ne yapıyor?","hint":"It is an autonomous audiometer. It measures how well a person can hear.","keys":["audiometer","measure","autonomous"]},{"ai":"How does the patient use it?","aiTr":"Hasta nasıl kullanıyor?","hint":"The patient puts on the headphones and follows the instructions. When they hear a sound, they press a button.","keys":["headphones","instructions","button"]},{"ai":"And how long does it take?","aiTr":"Peki ne kadar sürüyor?","hint":"Less than ten minutes, and no expert needs to be in the room.","keys":["minutes","less than","expert"]}]}},"st-02":{"intro":"Haftalık toplantıyı, görev dağılımını ve ekibe nasıl davrandığını anlatıyorsun.","text":[{"en":"I manage a small team, so communication is very important.","tr":"Küçük bir ekibi yönetiyorum, bu yüzden iletişim çok önemli."},{"en":"Every Monday morning, we have a short team meeting.","tr":"Her pazartesi sabahı kısa bir ekip toplantısı yaparız."},{"en":"Everyone says what they did, what they will do and what is blocking them.","tr":"Herkes ne yaptığını, ne yapacağını ve onu neyin engellediğini söyler."},{"en":"I try to give clear tasks with a deadline.","tr":"Son tarihi olan net görevler vermeye çalışırım."},{"en":"For example, I might say: 'Please finish the test report by Friday.'","tr":"Örneğin şöyle diyebilirim: 'Lütfen test raporunu cumaya kadar bitir.'"},{"en":"When there's a problem, we solve it together and I don't blame anyone.","tr":"Bir sorun olduğunda birlikte çözeriz ve kimseyi suçlamam."},{"en":"I also give feedback often, both positive and negative.","tr":"Ayrıca hem olumlu hem olumsuz, sık sık geri bildirim veririm."},{"en":"I think a good leader listens more than they talk.","tr":"Bence iyi bir lider konuştuğundan daha çok dinler."},{"en":"In the end, I trust my team because they're experts in their work.","tr":"Sonuçta ekibime güveniyorum çünkü onlar kendi işlerinde uzman."}],"vocab":[{"en":"manage a team","tr":"bir ekibi yönetmek","ex":"I manage a small team of six people.","def":"to lead and organise a group of people"},{"en":"communication","tr":"iletişim","ex":"In a small team, communication is very important.","def":"sharing information with other people"},{"en":"team meeting","tr":"ekip toplantısı","ex":"We have a short team meeting on Mondays.","def":"a meeting for everyone in the team"},{"en":"task","tr":"görev","ex":"I give clear tasks.","def":"a piece of work someone must do"},{"en":"deadline","tr":"son teslim tarihi","ex":"The deadline is Friday.","def":"the time when work must be finished"},{"en":"blame","tr":"suçlamak","ex":"I don't blame anyone.","def":"to say a problem is someone's fault"},{"en":"give feedback","tr":"geri bildirim vermek","ex":"I give feedback often.","def":"to tell someone what is good or bad about their work"},{"en":"trust","tr":"güvenmek","ex":"I trust my team.","def":"to believe someone will do the right thing"}],"grammar":{"title":"So and because: result and reason","tr":"'Because' bir şeyin nedenini, 'so' ise sonucunu verir. 'Because' nedenin önüne, 'so' sonucun önüne gelir.","examples":["I manage a small team, so communication is very important.","I trust my team because they're experts in their work."]},"questions":[{"q":"When is the team meeting?","options":["Every Friday","Every day","Every Monday morning"],"a":2},{"q":"What does everyone talk about in the meeting?","options":["Their salary","Their work and what is blocking them","Their holiday plans"],"a":1},{"q":"What does the speaker do when there is a problem?","options":["Solves it with the team","Finds someone to blame","Ignores it"],"a":0},{"q":"Why does the speaker trust the team?","options":["They are friends","They work at night","They are experts in their work"],"a":2}],"gaps":[{"s":"I try to give clear tasks with a ___.","a":"deadline","hint":"son tarih"},{"s":"We solve it together and I don't ___ anyone.","a":"blame","hint":"suçlamak"},{"s":"I give ___ often, both positive and negative.","a":"feedback","hint":"geri bildirim"}],"order":[{"a":"Every Monday we have a short team meeting."},{"a":"A good leader listens more than they talk."}],"translate":[{"tr":"Ekibime güveniyorum çünkü onlar uzman.","en":"I trust my team because they're experts.","keys":["trust my team","because"]},{"tr":"Lütfen raporu cumaya kadar bitir.","en":"Please finish the report by Friday.","keys":["finish","report","by Friday"]}],"roleplay":{"persona":"New engineer","personaTr":"Yeni işe başlayan mühendis","scene":"Ekibe bu hafta katılan yeni yazılım mühendisi, nasıl çalıştığınızı soruyor.","turns":[{"ai":"Hi! It's my first week here. How does the team work?","aiTr":"Merhaba! Burada ilk haftam. Ekip nasıl çalışıyor?","hint":"Every Monday morning we have a short team meeting, and everyone says what they did.","keys":["meeting","Monday","everyone"]},{"ai":"What should I do if I have a problem with my task?","aiTr":"Görevimle ilgili bir sorunum olursa ne yapmalıyım?","hint":"Tell me early, and we'll solve it together. I don't blame anyone.","keys":["together","solve","blame","tell"]},{"ai":"Great. So what's my first task?","aiTr":"Harika. Peki ilk görevim ne?","hint":"Please finish the test report by Friday. That's your deadline.","keys":["deadline","report","Friday"]}]}},"te-01":{"intro":"Yapay zekânın sağlıktaki rolünü, artılarını ve eksilerini basit örneklerle anlatıyorsun.","text":[{"en":"Artificial intelligence, or AI, is changing healthcare in many ways.","tr":"Yapay zekâ, yani AI, sağlık hizmetlerini pek çok açıdan değiştiriyor."},{"en":"AI can check thousands of images faster than any human.","tr":"Yapay zekâ binlerce görüntüyü herhangi bir insandan daha hızlı inceleyebilir."},{"en":"For example, it can help doctors find cancer in an X-ray.","tr":"Örneğin doktorların röntgende kanseri bulmasına yardım edebilir."},{"en":"AI doesn't get tired, so it can work twenty-four hours a day.","tr":"Yapay zekâ yorulmaz, bu yüzden günde yirmi dört saat çalışabilir."},{"en":"But AI isn't perfect: it can make mistakes, and it needs good data.","tr":"Ama yapay zekâ mükemmel değil: Hata yapabilir ve iyi veriye ihtiyacı var."},{"en":"That's why a doctor should always check the result.","tr":"Bu yüzden sonucu her zaman bir doktor kontrol etmeli."},{"en":"In our company, we use AI to make hearing tests faster and more accurate.","tr":"Şirketimizde işitme testlerini daha hızlı ve daha doğru yapmak için yapay zekâ kullanıyoruz."},{"en":"The AI chooses the next sound based on the patient's answers.","tr":"Yapay zekâ, hastanın cevaplarına göre bir sonraki sesi seçiyor."},{"en":"We improve the system every month, so it gets better over time.","tr":"Sistemi her ay geliştiriyoruz, böylece zamanla daha iyi hale geliyor."}],"vocab":[{"en":"artificial intelligence","tr":"yapay zekâ","ex":"Artificial intelligence is changing healthcare."},{"en":"image","tr":"görüntü","ex":"AI can check thousands of images."},{"en":"get tired","tr":"yorulmak","ex":"AI doesn't get tired."},{"en":"make a mistake","tr":"hata yapmak","ex":"AI can make mistakes."},{"en":"data","tr":"veri","ex":"AI needs good data."},{"en":"check the result","tr":"sonucu kontrol etmek","ex":"A doctor should always check the result."},{"en":"accurate","tr":"doğru, isabetli","ex":"The test is faster and more accurate."},{"en":"over time","tr":"zamanla","ex":"The system gets better over time."}],"grammar":{"title":"Comparatives: faster, more accurate, better","tr":"Kısa sıfatlara -er ekleriz (fast → faster), uzun sıfatlarda 'more' kullanırız (more accurate). 'Good' düzensizdir: better. Karşılaştırılan şeyden önce 'than' gelir.","examples":["AI can check images faster than any human.","We make hearing tests more accurate.","The system gets better over time."]},"questions":[{"q":"What can AI do with images?","options":["Delete them","Check them faster than a human","Print them"],"a":1},{"q":"Why is AI not perfect?","options":["It is too slow","It is too expensive","It can make mistakes and needs good data"],"a":2},{"q":"Who should always check the result?","options":["A doctor","The patient","Nobody"],"a":0},{"q":"Why does the system get better over time?","options":["It gets older","Patients pay more","The company improves it every month"],"a":2}],"gaps":[{"s":"AI doesn't get ___, so it can work twenty-four hours a day.","a":"tired","hint":"yorgun"},{"s":"It can make mistakes, and it needs good ___.","a":"data","hint":"veri"},{"s":"The system gets better over ___.","a":"time","hint":"zamanla"}],"order":[{"a":"A doctor should always check the result."},{"a":"AI can check thousands of images faster than any human."}],"translate":[{"tr":"Yapay zekâ sağlık hizmetlerini değiştiriyor.","en":"AI is changing healthcare.","keys":["changing","healthcare"]},{"tr":"Sistemi her ay geliştiriyoruz.","en":"We improve the system every month.","keys":["improve","every month"]}],"roleplay":{"persona":"Skeptical doctor","personaTr":"Şüpheci doktor","scene":"Yaşlı bir doktor yapay zekânın hastanede neden gerekli olduğunu soruyor.","turns":[{"ai":"Why do we need AI in a hospital? We have doctors.","aiTr":"Hastanede neden yapay zekâya ihtiyacımız var? Doktorlarımız var.","hint":"AI can check thousands of images faster than a human, and it doesn't get tired.","keys":["faster","tired","images","thousands"]},{"ai":"But AI makes mistakes, doesn't it?","aiTr":"Ama yapay zekâ hata yapıyor, değil mi?","hint":"Yes, AI isn't perfect. That's why a doctor should always check the result.","keys":["mistake","perfect","check","doctor"]},{"ai":"How do you use AI in your device?","aiTr":"Cihazınızda yapay zekâyı nasıl kullanıyorsunuz?","hint":"We use AI to make hearing tests faster and more accurate.","keys":["accurate","faster","hearing tests"]}]}},"te-03":{"intro":"Geçen hafta yaşanan teknik bir sorunu ve onu nasıl çözdüğünüzü anlatıyorsun.","text":[{"who":"Me","en":"Last week, we had a strange problem with our device.","tr":"Geçen hafta cihazımızla ilgili garip bir sorun yaşadık."},{"who":"Me","en":"Some clinics got wrong results at high frequencies, but others were fine.","tr":"Bazı klinikler yüksek frekanslarda yanlış sonuç aldı, ama diğerlerinde sorun yoktu."},{"who":"Me","en":"At first, we thought it was the headphones, but we were wrong.","tr":"İlk başta sorunun kulaklıklarda olduğunu düşündük, ama yanılmışız."},{"who":"Me","en":"So we collected data from all the devices and compared the clinics.","tr":"Bu yüzden tüm cihazlardan veri topladık ve klinikleri karşılaştırdık."},{"who":"Me","en":"The problem only happened in rooms with old air conditioners.","tr":"Sorun yalnızca eski klimaların olduğu odalarda ortaya çıkıyordu."},{"who":"Me","en":"Their noise was too loud at exactly those high frequencies.","tr":"Klimaların gürültüsü tam da o yüksek frekanslarda çok fazlaydı."},{"who":"Me","en":"We added a noise check before every test.","tr":"Her testten önce bir gürültü kontrolü ekledik."},{"who":"Me","en":"Now, if the room is too noisy, the device warns the user.","tr":"Artık oda fazla gürültülüyse cihaz kullanıcıyı uyarıyor."},{"who":"Me","en":"Our lesson: look at the data before you guess.","tr":"Çıkardığımız ders: tahmin etmeden önce verilere bak."}],"vocab":[{"en":"strange","tr":"garip, tuhaf","ex":"We had a strange problem with our device."},{"en":"high frequency","tr":"yüksek frekans","ex":"The results were wrong at high frequencies."},{"en":"at first","tr":"ilk başta","ex":"At first, we thought it was the headphones."},{"en":"collect data","tr":"veri toplamak","ex":"We collected data from all the devices."},{"en":"compare","tr":"karşılaştırmak","ex":"We compared the clinics."},{"en":"happen","tr":"olmak, meydana gelmek","ex":"The problem only happened in some rooms."},{"en":"warn","tr":"uyarmak","ex":"The device warns the user."},{"en":"guess","tr":"tahmin etmek","ex":"Look at the data before you guess."}],"grammar":{"title":"Past simple: what happened","tr":"Geçmişte olup bitmiş olaylar için past simple kullanılır. Düzenli fiillere -ed eklenir (collected, compared); bazı fiiller düzensizdir (have → had, think → thought).","examples":["We had a strange problem.","We collected data from all the devices.","At first, we thought it was the headphones."]},"questions":[{"q":"Where were the results wrong?","options":["In every clinic","In some clinics","Only in the office"],"a":1},{"q":"What did they think at first?","options":["The headphones were the problem","The software was old","The doctors made mistakes"],"a":0},{"q":"What caused the problem?","options":["Bad headphones","A slow computer","Noise from old air conditioners"],"a":2},{"q":"What does the device do now in a noisy room?","options":["It stops working","It warns the user","It calls the company"],"a":1}],"gaps":[{"s":"We ___ data from all the devices.","a":"collected","hint":"topladık"},{"s":"At ___, we thought it was the headphones.","a":"first","hint":"ilk başta"},{"s":"Look at the data before you ___.","a":"guess","hint":"tahmin etmek"}],"order":[{"a":"The problem only happened in rooms with old air conditioners."},{"a":"We added a noise check before every test."}],"translate":[{"tr":"Tüm cihazlardan veri topladık.","en":"We collected data from all the devices.","keys":["collected data","all the devices"]},{"tr":"Sorun kulaklıklar değildi.","en":"The problem was not the headphones.","keys":["problem","headphones"]}],"roleplay":{"persona":"Clinic manager","personaTr":"Klinik müdürü","scene":"Bir klinik müdürü geçen haftaki sorunun ne olduğunu ve nasıl çözüldüğünü soruyor.","turns":[{"ai":"We heard that some clinics had wrong results. What happened?","aiTr":"Bazı kliniklerin yanlış sonuç aldığını duyduk. Ne oldu?","hint":"The results were wrong at high frequencies, so we collected data from all the devices.","keys":["high frequencies","collected data","wrong"]},{"ai":"Was it a problem with the headphones?","aiTr":"Kulaklıklarla ilgili bir sorun muydu?","hint":"No, it wasn't. The noise from old air conditioners was too loud.","keys":["air conditioners","noise","too loud"]},{"ai":"How did you fix it?","aiTr":"Nasıl düzelttiniz?","hint":"We added a noise check. Now the device warns the user if the room is too noisy.","keys":["noise check","warns","too noisy"]}]}},"te-04":{"intro":"Bir mühendisle bulut ve cihaz seçeneklerini karşılaştırıp karar veriyorsun.","text":[{"who":"Engineer","en":"We need to decide where to run the AI.","tr":"Yapay zekâyı nerede çalıştıracağımıza karar vermemiz gerekiyor."},{"who":"Me","en":"What are the advantages of the cloud?","tr":"Bulutun avantajları neler?"},{"who":"Engineer","en":"The cloud is more powerful, and updates are easier.","tr":"Bulut daha güçlü ve güncellemeler daha kolay."},{"who":"Engineer","en":"But it needs the internet, and some hospitals don't let data leave the building.","tr":"Ama internet gerektiriyor ve bazı hastaneler verinin binadan çıkmasına izin vermiyor."},{"who":"Me","en":"And what about the device?","tr":"Peki ya cihaz?"},{"who":"Engineer","en":"The data stays private and the test works offline, but the hardware costs more.","tr":"Veri gizli kalıyor ve test internetsiz çalışıyor, ama donanım daha pahalıya mal oluyor."},{"who":"Me","en":"We're going to run the AI on the device because privacy matters most.","tr":"Yapay zekâyı cihazda çalıştıracağız, çünkü en önemli şey gizlilik."},{"who":"Me","en":"We can send updates once a month when the device is online.","tr":"Cihaz internete bağlandığında ayda bir güncelleme gönderebiliriz."},{"who":"Engineer","en":"OK, that makes sense to me.","tr":"Tamam, bence mantıklı."}],"vocab":[{"en":"decide","tr":"karar vermek","ex":"We need to decide where to run the AI."},{"en":"advantage","tr":"avantaj","ex":"What are the advantages of the cloud?"},{"en":"powerful","tr":"güçlü","ex":"The cloud is more powerful."},{"en":"let","tr":"izin vermek","ex":"Some hospitals don't let data leave the building."},{"en":"offline","tr":"çevrimdışı, internetsiz","ex":"The test works offline."},{"en":"cost more","tr":"daha pahalı olmak","ex":"The hardware costs more."},{"en":"once a month","tr":"ayda bir","ex":"We send updates once a month."},{"en":"That makes sense.","tr":"Mantıklı.","ex":"That makes sense to me."}],"grammar":{"title":"Comparatives: more powerful, easier","tr":"İki şeyi karşılaştırırken kısa sıfatlara -er eklenir (easy → easier), uzun sıfatların önüne 'more' gelir (more powerful). Ardından 'than' gelebilir.","examples":["The cloud is more powerful than the device.","Updates are easier in the cloud.","The hardware costs more."]},"questions":[{"q":"What is one advantage of the cloud?","options":["It is cheaper","It works offline","It is more powerful"],"a":2},{"q":"Why don't some hospitals like the cloud?","options":["It is too slow","They don't let data leave the building","It is too expensive"],"a":1},{"q":"What is the problem with running the AI on the device?","options":["The hardware costs more","The data is not private","It needs the internet"],"a":0},{"q":"How often will they send updates?","options":["Once a week","Once a month","Once a year"],"a":1}],"gaps":[{"s":"What are the ___ of the cloud?","a":"advantages","hint":"avantajlar"},{"s":"On the device, the test works ___.","a":"offline","hint":"internetsiz"},{"s":"We can send updates once a ___.","a":"month","hint":"ay"}],"order":[{"a":"We need to decide where to run the AI."},{"a":"We can send updates once a month."}],"translate":[{"tr":"Bulut daha güçlü.","en":"The cloud is more powerful.","keys":["more powerful"]},{"tr":"Bence mantıklı.","en":"That makes sense to me.","keys":["makes sense"]}],"roleplay":{"persona":"Hospital IT manager","personaTr":"Hastane bilgi işlem müdürü","scene":"Bir hastanenin bilgi işlem müdürü hasta verisinin nereye gittiğini soruyor.","turns":[{"ai":"Does your device send patient data to the internet?","aiTr":"Cihazınız hasta verisini internete gönderiyor mu?","hint":"No, it doesn't. The AI runs on the device, so the data stays private.","keys":["runs on the device","private","stays"]},{"ai":"Why didn't you use the cloud? It's more powerful.","aiTr":"Neden bulutu kullanmadınız? Daha güçlü.","hint":"Yes, but privacy is more important for hospitals, so we chose the device.","keys":["privacy","chose the device","more important"]},{"ai":"How do you update the software?","aiTr":"Yazılımı nasıl güncelliyorsunuz?","hint":"We send updates once a month when the device is online.","keys":["once a month","updates","online"]}]}},"sc-01":{"intro":"Klinik çalışmanı geçmiş zamanla anlatıyorsun: ne yaptınız, kaç kişi katıldı, sonuç ne oldu?","text":[{"en":"We needed to show that our device works as well as an audiologist.","tr":"Cihazımızın bir odyolog kadar iyi çalıştığını göstermemiz gerekiyordu."},{"en":"So we did a clinical study with two university hospitals.","tr":"Bu yüzden iki üniversite hastanesiyle bir klinik çalışma yaptık."},{"en":"Our goal was the same result in at least 90 percent of patients.","tr":"Hedefimiz hastaların en az yüzde 90'ında aynı sonuçtu."},{"en":"We found 200 people between 18 and 75 years old.","tr":"18 ile 75 yaş arasında 200 kişi bulduk."},{"en":"Each person did one test with our device and one with an audiologist.","tr":"Her kişi bir testi cihazımızla, bir testi de bir odyologla yaptı."},{"en":"The audiologist didn't see our results, so the comparison was blind.","tr":"Odyolog bizim sonuçlarımızı görmedi, yani karşılaştırma kördü."},{"en":"The results were the same in 94 percent of cases.","tr":"Sonuçlar vakaların yüzde 94'ünde aynıydı."},{"en":"In the other 6 percent, the difference was very small.","tr":"Diğer yüzde 6'da fark çok küçüktü."},{"en":"We published the study in a medical journal last spring.","tr":"Çalışmayı geçen bahar bir tıp dergisinde yayımladık."}],"vocab":[{"en":"clinical study","tr":"klinik çalışma","ex":"We did a clinical study with two hospitals."},{"en":"at least","tr":"en az","ex":"We wanted the same result in at least 90 percent of patients."},{"en":"patient","tr":"hasta","ex":"The study had patients between 18 and 75."},{"en":"blind","tr":"kör (sonucu bilmeden)","ex":"The audiologist didn't see our results, so the comparison was blind."},{"en":"difference","tr":"fark","ex":"The difference was very small."},{"en":"publish","tr":"yayımlamak","ex":"We published the study last spring."},{"en":"medical journal","tr":"tıp dergisi","ex":"The study is in a medical journal."}],"grammar":{"title":"Past simple: regular and irregular verbs","tr":"Geçmişte bitmiş olaylar için past simple kullanılır. Düzenli fiiller -ed alır (needed, published); düzensiz fiillerin özel hali vardır (do → did, find → found, be → was/were).","examples":["We needed to show that our device works.","We found 200 people.","The results were the same in 94 percent of cases."]},"questions":[{"q":"Who did they work with?","options":["Two university hospitals","One private clinic","A hearing aid shop"],"a":0},{"q":"How old were the participants?","options":["Under 18","Between 18 and 75","Over 75"],"a":1},{"q":"Why was the comparison blind?","options":["The patients closed their eyes","The tests were in the dark","The audiologist didn't see the device results"],"a":2},{"q":"What happened last spring?","options":["They started the study","They published the study","They found 200 people"],"a":1}],"gaps":[{"s":"We did a clinical study with two university ___.","a":"hospitals","hint":"hastaneler"},{"s":"Our goal was the same result in at ___ 90 percent of patients.","a":"least","hint":"en az"},{"s":"We ___ the study in a medical journal last spring.","a":"published","hint":"yayımladık"}],"order":[{"a":"The results were the same in 94 percent of cases."},{"a":"Each person did one test with our device."}],"translate":[{"tr":"Fark çok küçüktü.","en":"The difference was very small.","keys":["difference","small"]},{"tr":"Çalışmayı bir tıp dergisinde yayımladık.","en":"We published the study in a medical journal.","keys":["published","medical journal"]}],"roleplay":{"persona":"University researcher","personaTr":"Üniversite araştırmacısı","scene":"Bir konferansta bir araştırmacı klinik çalışmanızı soruyor.","turns":[{"ai":"Hi! I read about your clinical study. Why did you do it?","aiTr":"Merhaba! Klinik çalışmanızı okudum. Neden yaptınız?","hint":"We needed to show that our device works as well as an audiologist.","keys":["needed to show","works as well","audiologist"]},{"ai":"How many people took part?","aiTr":"Kaç kişi katıldı?","hint":"200 people between 18 and 75 years old took part.","keys":["200","18 and 75","took part"]},{"ai":"And what were the results?","aiTr":"Peki sonuçlar neydi?","hint":"The results were the same in 94 percent of cases.","keys":["94 percent","the same"]}]}},"te-02":{"intro":"İki yıl önce ve bugün kod yazma şeklinizi karşılaştırıyorsun.","text":[{"en":"Two years ago, our engineers wrote every line of code by hand.","tr":"İki yıl önce mühendislerimiz her kod satırını elle yazıyordu."},{"en":"Today we use AI coding assistants for a big part of our work.","tr":"Bugün işimizin büyük bir kısmı için yapay zekâ kod asistanları kullanıyoruz."},{"en":"An assistant can write code, explain it and find bugs.","tr":"Bir asistan kod yazabilir, kodu açıklayabilir ve hataları bulabilir."},{"en":"We describe what we want in plain English, and it writes a first version.","tr":"Ne istediğimizi sade bir İngilizceyle anlatıyoruz, o da ilk sürümü yazıyor."},{"en":"Then our engineers review the code and test it carefully.","tr":"Sonra mühendislerimiz kodu inceleyip dikkatle test ediyor."},{"en":"A task that took a week now takes a day or two.","tr":"Eskiden bir hafta süren bir iş artık bir iki gün sürüyor."},{"en":"But AI code can look correct and still have hidden problems.","tr":"Ama yapay zekânın yazdığı kod doğru görünüp yine de gizli sorunlar içerebilir."},{"en":"So we never release code without a human review and automatic tests.","tr":"Bu yüzden insan incelemesi ve otomatik testler olmadan asla kod yayınlamıyoruz."},{"en":"For a small startup like ours, it's like having three extra engineers.","tr":"Bizimki gibi küçük bir girişim için bu, üç ekstra mühendise sahip olmak gibi."}],"vocab":[{"en":"by hand","tr":"elle","ex":"We wrote every line of code by hand."},{"en":"coding assistant","tr":"kod asistanı","ex":"We use AI coding assistants."},{"en":"bug","tr":"yazılım hatası","ex":"The assistant can find bugs."},{"en":"plain English","tr":"sade İngilizce","ex":"We describe the task in plain English."},{"en":"review","tr":"incelemek","ex":"Our engineers review the code."},{"en":"hidden","tr":"gizli","ex":"AI code can have hidden problems."},{"en":"release","tr":"yayınlamak","ex":"We never release code without tests."},{"en":"extra","tr":"ekstra, fazladan","ex":"It's like having three extra engineers."}],"grammar":{"title":"Past simple vs present simple: then and now","tr":"Geçmişte bitmiş durumlar için past simple (wrote, took), bugünkü alışkanlıklar için present simple (use, takes) kullanırız. 'Two years ago' ve 'today' gibi zaman ifadeleri ipucu verir.","examples":["Two years ago, our engineers wrote every line of code by hand.","Today we use AI coding assistants.","A task that took a week now takes a day or two."]},"questions":[{"q":"How did the engineers write code two years ago?","options":["With AI","By hand","They didn't write code"],"a":1},{"q":"What does the assistant write after the team describes the task?","options":["A first version of the code","A report for investors","The final product"],"a":0},{"q":"What is the problem with AI code?","options":["It's too slow","It's too expensive","It can look correct but have hidden problems"],"a":2},{"q":"What do they always do before releasing code?","options":["Ask the customers","Wait a week","Nothing special","A human review and automatic tests"],"a":3}],"gaps":[{"s":"Two years ago, we wrote every line of code by ___.","a":"hand","hint":"elle (by …)"},{"s":"We describe what we want in ___ English.","a":"plain","hint":"sade"},{"s":"AI code can look correct and still have ___ problems.","a":"hidden","hint":"gizli"}],"order":[{"a":"A task that took a week now takes a day or two."},{"a":"Our engineers review the code and test it."}],"translate":[{"tr":"Bu, üç ekstra mühendise sahip olmak gibi.","en":"It's like having three extra engineers.","keys":["like having","three extra engineers"]},{"tr":"İki yıl önce kodu elle yazdık.","en":"Two years ago, we wrote the code by hand.","keys":["two years ago","by hand"]}],"roleplay":{"persona":"Tech investor","personaTr":"Teknoloji yatırımcısı","scene":"Bir yatırımcı küçük ekibinizin nasıl bu kadar hızlı ürün çıkardığını soruyor.","turns":[{"ai":"Your team is very small. How do you build software so fast?","aiTr":"Ekibiniz çok küçük. Yazılımı nasıl bu kadar hızlı geliştiriyorsunuz?","hint":"We use AI coding assistants. We describe what we want, and the assistant writes a first version.","keys":["coding assistants","describe","first version"]},{"ai":"Can you trust AI code?","aiTr":"Yapay zekânın yazdığı koda güvenebilir misiniz?","hint":"Not always, because it can have hidden problems. So our engineers review it and test it.","keys":["hidden problems","review","test"]},{"ai":"How much time does it save?","aiTr":"Ne kadar zaman kazandırıyor?","hint":"A lot. A task that took a week now takes a day or two.","keys":["a day or two","took a week","a lot"]}]}},"sc-02":{"intro":"Geçen yıl bir hibeye nasıl başvurduğunuzu geçmiş zamanla anlatıyorsun.","text":[{"en":"Not all money for a startup comes from investors.","tr":"Bir girişimin parasının hepsi yatırımcılardan gelmez."},{"en":"A grant is money that you don't have to pay back.","tr":"Hibe, geri ödemek zorunda olmadığınız paradır."},{"en":"Last year, we applied for a European innovation grant for health technology.","tr":"Geçen yıl sağlık teknolojisi için bir Avrupa inovasyon hibesine başvurduk."},{"en":"In the application, we described the problem, our solution, the team and the budget.","tr":"Başvuruda sorunu, çözümümüzü, ekibi ve bütçeyi anlattık."},{"en":"We also explained how many people our device can help.","tr":"Ayrıca cihazımızın kaç kişiye yardım edebileceğini açıkladık."},{"en":"The review took four months, and then we had an interview with a jury.","tr":"Değerlendirme dört ay sürdü, sonra bir jüriyle mülakatımız oldu."},{"en":"In the end, we won 250,000 euros.","tr":"Sonunda 250.000 euro kazandık."},{"en":"The money is only for research and clinical validation.","tr":"Para yalnızca araştırma ve klinik doğrulama için."},{"en":"Grants are slow, but they are great for early research.","tr":"Hibeler yavaştır ama erken aşama araştırma için harikadır."}],"vocab":[{"en":"grant","tr":"hibe","ex":"We applied for a European grant."},{"en":"pay back","tr":"geri ödemek","ex":"You don't have to pay back a grant."},{"en":"apply for","tr":"...e başvurmak","ex":"Last year, we applied for a grant."},{"en":"application","tr":"başvuru","ex":"The application was very long."},{"en":"budget","tr":"bütçe","ex":"We described the budget in the application."},{"en":"jury","tr":"jüri","ex":"We had an interview with a jury."},{"en":"early research","tr":"erken aşama araştırma","ex":"Grants are great for early research."}],"grammar":{"title":"Past simple: applied, took, won","tr":"Geçmişte bitmiş olaylar için past simple kullanılır. Düzenli fiiller -ed alır (applied, described); düzensiz fiillerin özel hali vardır (take → took, win → won, have → had).","examples":["Last year, we applied for a grant.","The review took four months.","In the end, we won 250,000 euros."]},"questions":[{"q":"What is a grant?","options":["A loan from a bank","Money you don't have to pay back","Money from customers"],"a":1},{"q":"What did they describe in the application?","options":["Only the price","Their office and cars","The problem, solution, team and budget"],"a":2},{"q":"How long did the review take?","options":["Four months","Four weeks","One year"],"a":0},{"q":"How much did they win?","options":["25,000 euros","250,000 euros","500,000 euros"],"a":1}],"gaps":[{"s":"Last year, we ___ for a European innovation grant.","a":"applied","hint":"başvurduk"},{"s":"The review ___ four months.","a":"took","hint":"sürdü"},{"s":"Then we had an interview with a ___.","a":"jury","hint":"jüri"}],"order":[{"a":"The money is only for research and clinical validation."},{"a":"Not all money for a startup comes from investors."}],"translate":[{"tr":"Geçen yıl bir hibeye başvurduk.","en":"Last year, we applied for a grant.","keys":["applied for","grant"]},{"tr":"Hibeler yavaştır ama erken aşama araştırma için harikadır.","en":"Grants are slow, but they are great for early research.","keys":["grants","early research"]}],"roleplay":{"persona":"Grant jury member","personaTr":"Hibe jürisi üyesi","scene":"Hibe mülakatındasın. Jüri projenin önemini ve paranın kullanımını soruyor.","turns":[{"ai":"Thank you for coming. Why is your project important?","aiTr":"Geldiğiniz için teşekkürler. Projeniz neden önemli?","hint":"One in five people has some hearing loss, but most people never do a test.","keys":["one in five","hearing loss","test"]},{"ai":"How are you going to use the money?","aiTr":"Parayı nasıl kullanacaksınız?","hint":"We are going to use it for research and clinical validation.","keys":["going to","research","clinical validation"]},{"ai":"Why should we choose your team?","aiTr":"Neden sizin ekibinizi seçmeliyiz?","hint":"We already have a working prototype, and our team has engineers and a doctor.","keys":["prototype","engineers","doctor"]}]}},"ai-04":{"intro":"Bir yatırımcıya CE işaretini, risk sınıfını ve klinik testleri basitçe anlatıyorsun.","text":[{"en":"Before we can sell our audiometer in Europe, we need a CE mark.","tr":"Odyometremizi Avrupa'da satabilmemiz için önce CE işaretine ihtiyacımız var."},{"en":"Later, we also want to get FDA approval for the United States.","tr":"Daha sonra Amerika Birleşik Devletleri için FDA onayı da almak istiyoruz."},{"en":"Our device is Class IIa, so it has a medium level of risk.","tr":"Cihazımız Sınıf IIa, yani orta düzeyde bir riske sahip."},{"en":"We need to prove that it is safe and that it works well.","tr":"Güvenli olduğunu ve iyi çalıştığını kanıtlamamız gerekiyor."},{"en":"We tested it with 200 people in two university hospitals.","tr":"Onu iki üniversite hastanesinde 200 kişiyle test ettik."},{"en":"Our results matched an audiologist's results in 94% of cases.","tr":"Vakaların %94'ünde sonuçlarımız bir odyoloğun sonuçlarıyla eşleşti."},{"en":"There is also a lot of paperwork, so the process is slow and expensive.","tr":"Ayrıca çok fazla evrak işi var, bu yüzden süreç yavaş ve pahalı."},{"en":"Our plan is to get the CE mark by the end of next year.","tr":"Planımız CE işaretini gelecek yılın sonuna kadar almak."},{"en":"An experienced consultant helps us, but it may take longer than planned.","tr":"Deneyimli bir danışman bize yardım ediyor ama planlanandan uzun sürebilir."}],"vocab":[{"en":"CE mark","tr":"CE işareti","ex":"We need a CE mark to sell in Europe."},{"en":"approval","tr":"onay","ex":"We want FDA approval later."},{"en":"level of risk","tr":"risk düzeyi","ex":"The device has a medium level of risk."},{"en":"prove","tr":"kanıtlamak","ex":"We need to prove that the device is safe."},{"en":"match","tr":"eşleşmek, uyuşmak","ex":"Our results matched the audiologist's results."},{"en":"paperwork","tr":"evrak işi","ex":"Certification needs a lot of paperwork."},{"en":"consultant","tr":"danışman","ex":"An experienced consultant helps us."},{"en":"take longer than planned","tr":"planlanandan uzun sürmek","ex":"Certification may take longer than planned."}],"grammar":{"title":"Past simple: what we did","tr":"Geçmişte bitmiş işler için past simple kullanırız. Düzenli fiillere -ed eklenir: test → tested, match → matched. Soru ve olumsuzda 'did' kullanılır.","examples":["We tested it with 200 people.","Our results matched an audiologist's results.","Did you test it in a hospital?"]},"questions":[{"q":"Why does the company need a CE mark?","options":["To get a bank loan","To sell the device in Europe","To hire more staff"],"a":1},{"q":"How many people took part in the tests?","options":["94","2,000","200"],"a":2},{"q":"Who is helping the company?","options":["An experienced consultant","A big hospital","The FDA"],"a":0},{"q":"What is the problem with the process?","options":["It is too easy","It is slow and expensive","It is not necessary"],"a":1}],"gaps":[{"s":"Our device is Class IIa, so it has a medium level of ___.","a":"risk","hint":"risk"},{"s":"We need to ___ that it is safe.","a":"prove","hint":"kanıtlamak"},{"s":"Our results ___ an audiologist's results in 94% of cases.","a":"matched","hint":"eşleşti"}],"order":[{"a":"We tested it with 200 people in two hospitals."},{"a":"Later we want to get FDA approval too."}],"translate":[{"tr":"Cihazın güvenli olduğunu kanıtlamamız gerekiyor.","en":"We need to prove that the device is safe.","keys":["prove","safe"]},{"tr":"Süreç yavaş ve pahalı.","en":"The process is slow and expensive.","keys":["slow","expensive"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Bir yatırımcı sertifikasyonu ve klinik testleri soruyor.","turns":[{"ai":"Can you sell the device in Europe today?","aiTr":"Cihazı bugün Avrupa'da satabilir misiniz?","hint":"Not yet. We need a CE mark first, because it is a medical device.","keys":["CE mark","not yet","medical device"]},{"ai":"How did you prove that it works?","aiTr":"Çalıştığını nasıl kanıtladınız?","hint":"We tested it with 200 people in two hospitals. Our results matched an audiologist's results in 94% of cases.","keys":["200","94","matched","tested"]},{"ai":"When are you going to get the CE mark?","aiTr":"CE işaretini ne zaman alacaksınız?","hint":"By the end of next year, but it may take longer than planned.","keys":["next year","take longer","end of"]}]}},"st-03":{"intro":"Geçen ay verdiğiniz zor kararı ve nedenini anlatıyorsun.","text":[{"en":"Last month, we had to make a difficult decision.","tr":"Geçen ay zor bir karar vermek zorunda kaldık."},{"en":"We had two options for selling our device.","tr":"Cihazımızı satmak için iki seçeneğimiz vardı."},{"en":"Option A was to sell it directly to hospitals.","tr":"A seçeneği onu doğrudan hastanelere satmaktı."},{"en":"Option B was to work with a distributor who already knows the market.","tr":"B seçeneği pazarı zaten bilen bir distribütörle çalışmaktı."},{"en":"Selling directly gives us more profit, but it takes a lot of time.","tr":"Doğrudan satmak bize daha çok kâr sağlıyor ama çok zaman alıyor."},{"en":"A distributor takes a percentage, but they can reach customers much faster.","tr":"Distribütör bir yüzde alıyor ama müşterilere çok daha hızlı ulaşabiliyor."},{"en":"We talked about the pros and cons for two weeks.","tr":"İki hafta boyunca artıları ve eksileri konuştuk."},{"en":"In the end, we chose the distributor because speed is very important.","tr":"Sonunda distribütörü seçtik çünkü hız çok önemli."},{"en":"It wasn't an easy choice, but I think it was the right one.","tr":"Kolay bir seçim değildi ama bence doğru olandı."}],"vocab":[{"en":"make a decision","tr":"karar vermek","ex":"We had to make a difficult decision.","def":"to choose after thinking"},{"en":"option","tr":"seçenek","ex":"We had two options.","def":"something you can choose"},{"en":"directly","tr":"doğrudan","ex":"We could sell directly to hospitals.","def":"without anyone in the middle"},{"en":"distributor","tr":"distribütör, dağıtıcı","ex":"A distributor already knows the market.","def":"a company that sells another company's products"},{"en":"profit","tr":"kâr","ex":"Selling directly gives us more profit.","def":"the money you keep after paying costs"},{"en":"take a percentage","tr":"yüzde almak, pay almak","ex":"A distributor takes a percentage.","def":"to keep a part of the money from each sale"},{"en":"reach customers","tr":"müşterilere ulaşmak","ex":"They can reach customers much faster.","def":"to find and talk to people who might buy"},{"en":"pros and cons","tr":"artılar ve eksiler","ex":"We talked about the pros and cons.","def":"the good and bad sides of something"}],"grammar":{"title":"Past simple: what we did","tr":"Geçmişte bitmiş olaylar için past simple kullanırız. Düzenli fiiller -ed alır (talked), düzensiz fiiller değişir (have → had, choose → chose).","examples":["We had two options.","We talked about the pros and cons for two weeks.","In the end, we chose the distributor."]},"questions":[{"q":"When did they make the decision?","options":["Last year","Last month","Last week"],"a":1},{"q":"What was option A?","options":["Work with a distributor","Close the company","Sell directly to hospitals"],"a":2},{"q":"How long did they talk about it?","options":["Two weeks","Two days","Two months"],"a":0},{"q":"Why did they choose the distributor?","options":["It was cheaper","Speed is very important","The doctor wanted it"],"a":1}],"gaps":[{"s":"We had to make a difficult ___.","a":"decision","hint":"karar"},{"s":"We talked about the pros and ___ for two weeks.","a":"cons","hint":"eksiler"},{"s":"A distributor takes a ___, but they can reach customers faster.","a":"percentage","hint":"yüzde"}],"order":[{"a":"We had two options for selling our device."},{"a":"In the end we chose the distributor."}],"translate":[{"tr":"İki seçeneğimiz vardı.","en":"We had two options.","keys":["had two options"]},{"tr":"Kolay bir seçim değildi.","en":"It wasn't an easy choice.","keys":["easy choice"]}],"roleplay":{"persona":"Co-founder","personaTr":"Kurucu ortak","scene":"Kurucu ortağın, distribütör mü yoksa doğrudan satış mı sorusunu seninle konuşmak istiyor.","turns":[{"ai":"I think we should sell directly to hospitals. What do you think?","aiTr":"Bence doğrudan hastanelere satmalıyız. Sen ne düşünüyorsun?","hint":"Selling directly gives us more profit, but it takes a lot of time.","keys":["profit","time","but"]},{"ai":"But a distributor takes a percentage. Is that a problem?","aiTr":"Ama distribütör bir yüzde alıyor. Bu bir sorun mu?","hint":"Not really. They can reach customers much faster than us.","keys":["faster","reach","customers"]},{"ai":"So what's your decision?","aiTr":"Peki kararın ne?","hint":"I want to go with the distributor because speed is very important.","keys":["distributor","speed","because"]}]}},"li-01":{"intro":"İş seyahatinde pasaport kontrolü ve otel check-in konuşmaları.","text":[{"who":"Officer","en":"Good morning, what is the purpose of your visit?","tr":"Günaydın, ziyaretinizin amacı nedir?"},{"who":"Me","en":"I'm here for a business conference about medical technology.","tr":"Medikal teknoloji üzerine bir iş konferansı için buradayım."},{"who":"Officer","en":"How long are you going to stay?","tr":"Ne kadar kalacaksınız?"},{"who":"Me","en":"I'm staying for four days and flying back on Friday.","tr":"Dört gün kalıyorum ve cuma günü dönüyorum."},{"who":"Officer","en":"Thank you, and enjoy your stay.","tr":"Teşekkürler, iyi konaklamalar."},{"who":"Me","en":"Hello, I have a reservation under the name {name}.","tr":"Merhaba, {name} adına bir rezervasyonum var."},{"who":"Receptionist","en":"Welcome, could I see your passport, please?","tr":"Hoş geldiniz, pasaportunuzu görebilir miyim, lütfen?"},{"who":"Me","en":"Here you are, and is breakfast included?","tr":"Buyurun; kahvaltı dahil mi?"},{"who":"Receptionist","en":"Yes, from 7 to 10, and your room is on the fifth floor.","tr":"Evet, 7'den 10'a kadar; odanız da beşinci katta."}],"vocab":[{"en":"purpose of your visit","tr":"ziyaretinizin amacı","ex":"What is the purpose of your visit?"},{"en":"business conference","tr":"iş konferansı","ex":"I'm here for a business conference."},{"en":"fly back","tr":"uçakla dönmek","ex":"I'm flying back on Friday."},{"en":"Enjoy your stay.","tr":"İyi konaklamalar.","ex":"Thank you, and enjoy your stay."},{"en":"reservation under the name","tr":"... adına rezervasyon","ex":"I have a reservation under the name {name}."},{"en":"Could I see...?","tr":"...görebilir miyim?","ex":"Could I see your passport, please?"},{"en":"Here you are.","tr":"Buyurun.","ex":"Here you are, this is my passport."},{"en":"included","tr":"dahil","ex":"Is breakfast included?"}],"grammar":{"title":"Future plans: going to and present continuous","tr":"Gelecek planları için 'going to' ya da şimdiki zaman (present continuous) kullanılır. Özellikle bilet, tarih gibi kesinleşmiş planlarda present continuous çok doğaldır.","examples":["How long are you going to stay?","I'm staying for four days.","I'm flying back on Friday."]},"questions":[{"q":"Why is the speaker travelling?","options":["For a holiday","For a business conference","To visit family"],"a":1},{"q":"When does the speaker fly back?","options":["On Friday","On Monday","On Sunday"],"a":0},{"q":"What does the receptionist ask for?","options":["A credit card","A phone number","A passport"],"a":2},{"q":"When is breakfast?","options":["From 6 to 9","From 7 to 10","From 8 to 11"],"a":1}],"gaps":[{"s":"What is the ___ of your visit?","a":"purpose","hint":"amaç"},{"s":"I have a ___ under the name {name}.","a":"reservation","hint":"rezervasyon"},{"s":"Is breakfast ___?","a":"included","hint":"dahil"}],"order":[{"a":"How long are you going to stay?"},{"a":"Your room is on the fifth floor."}],"translate":[{"tr":"Bir iş konferansı için buradayım.","en":"I'm here for a business conference.","keys":["here for","business conference"]},{"tr":"Pasaportunuzu görebilir miyim?","en":"Could I see your passport?","keys":["could I see","passport"]}],"roleplay":{"persona":"Hotel receptionist","personaTr":"Otel resepsiyonisti","scene":"Berlin'de otele geç saatte giriş yapıyorsun.","turns":[{"ai":"Good evening! How can I help you?","aiTr":"İyi akşamlar! Nasıl yardımcı olabilirim?","hint":"Hello, I have a reservation under the name {name}.","keys":["reservation","under the name","hello"]},{"ai":"Welcome! Could I see your passport, please?","aiTr":"Hoş geldiniz! Pasaportunuzu görebilir miyim, lütfen?","hint":"Here you are. Is breakfast included?","keys":["here you are","breakfast","included"]},{"ai":"Yes, from 7 to 10. Your room is 512. Anything else?","aiTr":"Evet, 7'den 10'a kadar. Odanız 512. Başka bir şey?","hint":"Could you tell me the wifi password? And what time is check-out?","keys":["could you","wifi","check-out"]}]}},"co-01":{"intro":"Networking için kısa, doğal ve akılda kalıcı bir şekilde kendini tanıtıyorsun.","text":[{"who":"Me","en":"Hi, I don't think we've met — I'm {name}.","tr":"Merhaba, sanırım tanışmadık; ben {name}."},{"who":"Sarah","en":"Hi {name}, I'm Sarah, and I work for a hospital group in the UK.","tr":"Merhaba {name}, ben Sarah; İngiltere'de bir hastane grubunda çalışıyorum."},{"who":"Me","en":"I'm the founder of a medical device startup from Turkey.","tr":"Türkiye'den bir tıbbi cihaz girişiminin kurucusuyum."},{"who":"Sarah","en":"Oh, what kind of device?","tr":"Aa, ne tür bir cihaz?"},{"who":"Me","en":"It's a self-service audiometer, so you can test hearing without an expert.","tr":"Self servis bir odyometre, böylece işitmeyi uzman olmadan test edebiliyorsunuz."},{"who":"Sarah","en":"That sounds useful, because we have long waiting lists for hearing tests.","tr":"Kulağa faydalı geliyor, çünkü işitme testleri için uzun bekleme listelerimiz var."},{"who":"Me","en":"That's exactly the problem we solve.","tr":"Çözdüğümüz sorun tam olarak bu."},{"who":"Me","en":"Can I give you my card?","tr":"Size kartımı verebilir miyim?"},{"who":"Sarah","en":"Sure, let's talk more after the next session.","tr":"Tabii, bir sonraki oturumdan sonra daha fazla konuşalım."}],"vocab":[{"en":"I don't think we've met.","tr":"Sanırım tanışmadık.","ex":"Hi, I don't think we've met."},{"en":"work for","tr":"...de çalışmak","ex":"I work for a hospital group."},{"en":"founder","tr":"kurucu","ex":"I'm the founder of a medical device startup."},{"en":"What kind of...?","tr":"Ne tür...?","ex":"What kind of device is it?"},{"en":"self-service","tr":"self servis","ex":"It's like a self-service hearing test."},{"en":"That sounds useful.","tr":"Kulağa faydalı geliyor.","ex":"That sounds useful for our clinics."},{"en":"waiting list","tr":"bekleme listesi","ex":"We have long waiting lists."},{"en":"exactly","tr":"tam olarak","ex":"That's exactly the problem we solve."}],"grammar":{"title":"Linking with because and so","tr":"'because' bir sebep verir (çünkü), 'so' bir sonuç verir (bu yüzden, böylece). İki kısa cümleyi bağlayıp daha akıcı konuşmanı sağlar.","examples":["That sounds useful, because we have long waiting lists.","We make a self-service audiometer, so people don't need an expert.","I was busy, so I missed the first session."]},"questions":[{"q":"Where does Sarah work?","options":["At a hospital group in the UK","At a startup in Turkey","At a university in Ireland"],"a":0},{"q":"What is special about the audiometer?","options":["It is very cheap","People can test their hearing without an expert","It works only in hospitals"],"a":1},{"q":"What problem does Sarah have?","options":["Not enough money","Too many doctors","Long waiting lists for hearing tests"],"a":2},{"q":"What do they plan to do?","options":["Sign a contract today","Talk more after the next session","Have dinner tonight"],"a":1}],"gaps":[{"s":"Hi, I don't think we've ___.","a":"met","hint":"tanışmak"},{"s":"That ___ useful.","a":"sounds","hint":"kulağa geliyor"},{"s":"That's ___ the problem we solve.","a":"exactly","hint":"tam olarak"}],"order":[{"a":"Can I give you my card?"},{"a":"Let's talk more after the next session."}],"translate":[{"tr":"Tanıştığımıza memnun oldum.","en":"Nice to meet you.","keys":["nice to meet you"]},{"tr":"Ne tür bir cihaz?","en":"What kind of device?","keys":["what kind","device"]}],"roleplay":{"persona":"Conference attendee","personaTr":"Konferans katılımcısı","scene":"Kahve kuyruğunda yanındaki kişi seninle konuşmaya başlıyor.","turns":[{"ai":"Hi there! I'm Emma, from a clinic chain in Ireland. And you?","aiTr":"Merhaba! Ben Emma, İrlanda'daki bir klinik zincirindenim. Ya siz?","hint":"Nice to meet you, Emma. I'm {name}, and I'm the founder of a medical device startup from Turkey.","keys":["nice to meet","founder","startup","Turkey"]},{"ai":"What kind of device do you make?","aiTr":"Ne tür bir cihaz yapıyorsunuz?","hint":"We make a self-service audiometer, so people can test their hearing without an expert.","keys":["audiometer","hearing","expert","self-service"]},{"ai":"Interesting! We have very long waiting lists.","aiTr":"İlginç! Bizim çok uzun bekleme listelerimiz var.","hint":"That's exactly the problem we solve. Can I give you my card?","keys":["exactly","problem","card","solve"]}]}},"st-01":{"intro":"Bir kahve sohbetinde şirketini kısa ve net anlatıyorsun.","text":[{"who":"Partner","en":"So, tell me about your company.","tr":"Peki, bana şirketinden bahset."},{"who":"Me","en":"We are a medical technology startup from Turkey.","tr":"Biz Türkiye'den bir medikal teknoloji girişimiyiz."},{"who":"Me","en":"We build a device that tests hearing automatically.","tr":"İşitmeyi otomatik olarak test eden bir cihaz geliştiriyoruz."},{"who":"Partner","en":"Interesting, so who are your customers?","tr":"İlginç, peki müşterileriniz kimler?"},{"who":"Me","en":"Our customers are hospitals, clinics and hearing aid shops.","tr":"Müşterilerimiz hastaneler, klinikler ve işitme cihazı mağazaları."},{"who":"Me","en":"They need a fast and reliable test, but they don't have enough experts.","tr":"Hızlı ve güvenilir bir teste ihtiyaçları var ama yeterli uzmanları yok."},{"who":"Partner","en":"How big is your team?","tr":"Ekibiniz ne kadar büyük?"},{"who":"Me","en":"We're a small team of six: three engineers, one doctor and two business people.","tr":"Altı kişilik küçük bir ekibiz: üç mühendis, bir doktor ve iki iş insanı."},{"who":"Me","en":"Our next step is to find partners in Europe, and that's why I'm here.","tr":"Bir sonraki adımımız Avrupa'da ortaklar bulmak, bu yüzden buradayım."}],"vocab":[{"en":"startup","tr":"girişim, yeni kurulmuş şirket","ex":"We are a medical technology startup.","def":"a new company, often in technology"},{"en":"build a device","tr":"bir cihaz geliştirmek / üretmek","ex":"We build a device that tests hearing.","def":"to design and make a machine"},{"en":"customer","tr":"müşteri","ex":"Our customers are hospitals and clinics.","def":"a person or company that buys something"},{"en":"reliable","tr":"güvenilir","ex":"They need a fast and reliable test.","def":"that you can trust to work well"},{"en":"expert","tr":"uzman","ex":"They don't have enough experts.","def":"a person with special knowledge or skill"},{"en":"team of six","tr":"altı kişilik ekip","ex":"We're a small team of six.","def":"a group of six people who work together"},{"en":"next step","tr":"sonraki adım","ex":"Our next step is to find partners.","def":"the thing you plan to do after this"},{"en":"that's why","tr":"bu yüzden","ex":"That's why I'm here.","def":"for this reason"}],"grammar":{"title":"Linking ideas: but / that's why","tr":"'But' iki zıt fikri bağlar (ihtiyaçları var ama uzmanları yok). 'That's why' ise sonucu verir: 'bu yüzden'.","examples":["They need a fast test, but they don't have enough experts.","Our next step is to find partners, and that's why I'm here."]},"questions":[{"q":"What does the company build?","options":["A hearing aid","A device that tests hearing","A hospital app"],"a":1},{"q":"Who are the customers?","options":["Only hospitals","Schools and parents","Hospitals, clinics and hearing aid shops"],"a":2},{"q":"How many people are in the team?","options":["Three","Ten","Six"],"a":2},{"q":"Why is the speaker at the meeting?","options":["To find partners in Europe","To sell a hospital","To hire a doctor"],"a":0}],"gaps":[{"s":"We build a ___ that tests hearing automatically.","a":"device","hint":"cihaz"},{"s":"They need a fast and ___ test.","a":"reliable","hint":"güvenilir"},{"s":"Our next ___ is to find partners in Europe.","a":"step","hint":"adım"}],"order":[{"a":"We're a small team of six people."},{"a":"Our customers are hospitals and clinics."}],"translate":[{"tr":"Biz Türkiye'den bir medikal teknoloji girişimiyiz.","en":"We are a medical technology startup from Turkey.","keys":["startup","Turkey"]},{"tr":"Bu yüzden buradayım.","en":"That's why I'm here.","keys":["that's why","here"]}],"roleplay":{"persona":"Potential partner","personaTr":"Olası iş ortağı","scene":"Bir konferansta kahve molasında Almanya'dan bir klinik zinciri yöneticisiyle tanışıyorsun.","turns":[{"ai":"Nice to meet you. What does your company do?","aiTr":"Tanıştığımıza memnun oldum. Şirketiniz ne yapıyor?","hint":"We are a medical technology startup, and we build a device that tests hearing.","keys":["device","startup","hearing"]},{"ai":"Who uses it? Who are your customers?","aiTr":"Kim kullanıyor? Müşterileriniz kimler?","hint":"Our customers are hospitals, clinics and hearing aid shops.","keys":["customer","hospital","clinic"]},{"ai":"And why are you here in Europe?","aiTr":"Peki neden Avrupa'dasınız?","hint":"Our next step is to find partners in Europe, and that's why I'm here.","keys":["partner","next step","that's why"]}]}},"co-02":{"intro":"Konferanstan sonra Sarah'ya kısa ve kibar bir takip e-postası yazıyorsun.","text":[{"en":"Subject: Nice to meet you at MedTech Europe","tr":"Konu: MedTech Europe'ta tanıştığımıza memnun oldum"},{"en":"Dear Sarah,","tr":"Sevgili Sarah,"},{"en":"Thank you for the nice talk at the conference yesterday.","tr":"Dün konferanstaki keyifli sohbet için teşekkür ederim."},{"en":"It was interesting to hear about the long waiting lists in your hospitals.","tr":"Hastanelerinizdeki uzun bekleme listelerini dinlemek ilginçti."},{"en":"As I promised, I attached a short presentation about our audiometer.","tr":"Söz verdiğim gibi, odyometremiz hakkında kısa bir sunum ekledim."},{"en":"I'd like to give your team a short online demo.","tr":"Ekibinize kısa bir çevrimiçi demo yapmak isterim."},{"en":"Are you free next Tuesday or Wednesday afternoon?","tr":"Gelecek salı veya çarşamba öğleden sonra müsait misiniz?"},{"en":"Please let me know if you have any questions.","tr":"Herhangi bir sorunuz olursa lütfen bana bildirin."},{"en":"Best regards, {name}","tr":"Saygılarımla, {name}"}],"vocab":[{"en":"talk","tr":"sohbet, konuşma","ex":"Thank you for the nice talk yesterday."},{"en":"waiting list","tr":"bekleme listesi","ex":"The waiting lists in her hospitals are long."},{"en":"as I promised","tr":"söz verdiğim gibi","ex":"As I promised, I attached the presentation."},{"en":"attach","tr":"eklemek (dosya)","ex":"I attached a short presentation."},{"en":"online demo","tr":"çevrimiçi demo","ex":"I'd like to give your team an online demo."},{"en":"I'd like to","tr":"...mak isterim","ex":"I'd like to show you the device."},{"en":"be free","tr":"müsait olmak","ex":"Are you free next Tuesday?"},{"en":"let me know","tr":"bana haber verin","ex":"Please let me know if you have any questions."}],"grammar":{"title":"Past simple: what happened","tr":"Geçmişte olup bitmiş olaylar için past simple kullanılır. Düzenli fiillere -ed eklenir: attach → attached, promise → promised.","examples":["As I promised, I attached a short presentation.","We talked about waiting lists.","It was interesting to hear about your hospitals."]},"questions":[{"q":"When did they meet?","options":["Last week","Yesterday","Last month"],"a":1},{"q":"What did they talk about?","options":["Waiting lists in Sarah's hospitals","Prices of hearing aids","The weather in the UK"],"a":0},{"q":"What is attached to the email?","options":["A contract","A photo of the team","A short presentation"],"a":2},{"q":"What does the writer want to do next?","options":["Visit Sarah's hospital","Give Sarah's team an online demo","Sell the device today"],"a":1}],"gaps":[{"s":"As I promised, I ___ a short presentation about our audiometer.","a":"attached","hint":"ekledim"},{"s":"I'd like to give your team a short online ___.","a":"demo","hint":"demo, tanıtım"},{"s":"Please ___ me know if you have any questions.","a":"let","hint":"izin vermek (haber vermek)"}],"order":[{"a":"Are you free next Tuesday or Wednesday afternoon?"},{"a":"Please let me know if you have any questions."}],"translate":[{"tr":"Söz verdiğim gibi kısa bir sunum ekledim.","en":"As I promised, I attached a short presentation.","keys":["as I promised","attached"]},{"tr":"Ekibinize kısa bir çevrimiçi demo yapmak isterim.","en":"I'd like to give your team a short online demo.","keys":["online demo","your team"]}],"roleplay":{"persona":"Sarah (by email)","personaTr":"Sarah (e-posta ile)","scene":"Sarah e-postana cevap veriyor. Sen de kısa ve kibar cevaplar yazıyorsun.","turns":[{"ai":"Hi {name}, thanks for the presentation. A demo sounds good. When are you free?","aiTr":"Merhaba {name}, sunum için teşekkürler. Demo iyi fikir. Ne zaman müsaitsiniz?","hint":"Thank you, Sarah. Are you free next Tuesday or Wednesday afternoon?","keys":["Tuesday","Wednesday","afternoon"]},{"ai":"Wednesday at 2 pm is good for me. Who should come from my team?","aiTr":"Çarşamba 14:00 bana uyar. Ekibimden kim gelmeli?","hint":"I think your clinic manager and an audiologist should come. I'm going to send an invitation.","keys":["clinic manager","audiologist","invitation"]},{"ai":"Perfect. See you on Wednesday!","aiTr":"Mükemmel. Çarşamba görüşürüz!","hint":"Great, see you then. Please let me know if you have any questions. Best regards, {name}","keys":["let me know","questions","see you"]}]}},"fu-01":{"intro":"Bir sağlık teknolojisi konferansındaki panelde, bir doktorun 'Yapay zekâ doktorların yerini alacak mı?' sorusuna cevap veriyorsun.","text":[{"who":"Dr. Weber","en":"Many people say AI is going to replace doctors like me.","tr":"Birçok kişi yapay zekânın benim gibi doktorların yerini alacağını söylüyor."},{"who":"Me","en":"I don't agree, because AI should help doctors, not replace them.","tr":"Katılmıyorum, çünkü yapay zekâ doktorların yerini almamalı, onlara yardım etmeli."},{"who":"Me","en":"AI is faster than a person, and it never gets tired.","tr":"Yapay zekâ bir insandan daha hızlıdır ve hiç yorulmaz."},{"who":"Me","en":"But it makes mistakes, and it needs good data to learn.","tr":"Ama hata yapar ve öğrenmek için iyi veriye ihtiyaç duyar."},{"who":"Me","en":"When something goes wrong, a person needs to take responsibility.","tr":"Bir şey ters gittiğinde, bir insanın sorumluluk alması gerekir."},{"who":"Me","en":"Patients also want to talk to a person they trust.","tr":"Hastalar ayrıca güvendikleri bir insanla konuşmak ister."},{"who":"Me","en":"For example, our audiometer does a hearing test in under ten minutes.","tr":"Örneğin odyometremiz işitme testini on dakikadan kısa sürede yapıyor."},{"who":"Me","en":"There is no expert in the room, so audiologists have more time.","tr":"Odada uzman olması gerekmiyor, bu yüzden odyologların daha çok zamanı oluyor."},{"who":"Me","en":"They can use that time for the difficult cases.","tr":"Bu zamanı zor vakalar için kullanabilirler."}],"vocab":[{"en":"replace","tr":"yerini almak","ex":"AI is not going to replace doctors."},{"en":"faster than","tr":"...den daha hızlı","ex":"AI is faster than a person."},{"en":"get tired","tr":"yorulmak","ex":"AI never gets tired."},{"en":"make a mistake","tr":"hata yapmak","ex":"AI sometimes makes mistakes."},{"en":"go wrong","tr":"ters gitmek","ex":"When something goes wrong, a person is responsible."},{"en":"take responsibility","tr":"sorumluluk almak","ex":"A person needs to take responsibility."},{"en":"expert","tr":"uzman","ex":"There is no expert in the room."},{"en":"in under ten minutes","tr":"on dakikadan kısa sürede","ex":"Our audiometer does a test in under ten minutes."}],"grammar":{"title":"Comparatives: faster than, more time","tr":"İki şeyi karşılaştırırken kısa sıfatlara -er eklenir ve ardından 'than' gelir: fast → faster than. Uzun sıfatlarda ve isimlerde 'more' kullanılır: more time, more difficult.","examples":["AI is faster than a person.","Audiologists have more time.","Difficult cases need more time than simple tests."]},"questions":[{"q":"What does Dr. Weber talk about?","options":["The price of devices","AI replacing doctors","A new hospital"],"a":1},{"q":"What does AI need to learn?","options":["Good data","More doctors","A bigger room"],"a":0},{"q":"How long does the hearing test take?","options":["About an hour","Two days","Under ten minutes"],"a":2},{"q":"What can audiologists do with their extra time?","options":["Go home early","Work on difficult cases","Sell more devices"],"a":1}],"gaps":[{"s":"AI is faster than a person, and it never gets ___.","a":"tired","hint":"yorgun"},{"s":"When something goes wrong, a person needs to take ___.","a":"responsibility","hint":"sorumluluk"},{"s":"Our audiometer does a hearing test in under ten ___.","a":"minutes","hint":"dakika"}],"order":[{"a":"AI should help doctors not replace them."},{"a":"Patients want to talk to a person they trust."}],"translate":[{"tr":"Yapay zekâ doktorların yerini almamalı.","en":"AI should not replace doctors.","keys":["should not","replace doctors"]},{"tr":"Yapay zekâ bir insandan daha hızlıdır.","en":"AI is faster than a person.","keys":["faster than"]}],"roleplay":{"persona":"Skeptical doctor","personaTr":"Şüpheci doktor","scene":"Paneldeki şüpheci doktor yapay zekâya güvenmiyor. Ona sakin ve net cevaplar veriyorsun.","turns":[{"ai":"Is AI going to take my job?","aiTr":"Yapay zekâ işimi elimden mi alacak?","hint":"No, I don't think so. AI should help doctors, not replace them.","keys":["help doctors","not replace","don't think so"]},{"ai":"But what happens when the AI makes a mistake?","aiTr":"Ama yapay zekâ hata yaptığında ne olacak?","hint":"That's why a person needs to check the result and take responsibility.","keys":["take responsibility","check","person"]},{"ai":"So what does your device do for audiologists?","aiTr":"Peki cihazınız odyologlar için ne yapıyor?","hint":"It does simple hearing tests, so they have more time for difficult cases.","keys":["more time","difficult cases","hearing tests"]}]}},"ab-01":{"intro":"Berlin'de bir daire görmeye gidiyorsun; kira, faturalar, depozito, sözleşme ve gereken belgeleri soruyorsun.","text":[{"who":"Landlord","en":"Hello, I'm Mrs Becker, and this is the flat I told you about.","tr":"Merhaba, ben Bayan Becker; size bahsettiğim daire bu."},{"who":"Me","en":"It's bigger and brighter than the photos, and I really like the balcony.","tr":"Fotoğraflardakinden daha büyük ve daha aydınlık; balkonu da çok sevdim."},{"who":"Me","en":"How much is the rent, and are the bills included?","tr":"Kira ne kadar, faturalar dahil mi?"},{"who":"Landlord","en":"It's €1,200 a month with heating and water, but internet isn't included.","tr":"Isınma ve su dahil ayda 1.200 avro, ama internet dahil değil."},{"who":"Landlord","en":"I need a deposit of three months' rent, so that's €3,600.","tr":"Üç aylık kira tutarında depozito istiyorum, yani 3.600 avro."},{"who":"Me","en":"That's a lot at once, so can I pay it in three instalments?","tr":"Bir seferde bu çok fazla; üç taksitte ödeyebilir miyim?"},{"who":"Landlord","en":"Yes, that's fine, but the contract is for at least two years.","tr":"Evet, olur, ama sözleşme en az iki yıllık."},{"who":"Me","en":"No problem, because I'm going to stay in Berlin for a long time.","tr":"Sorun değil, çünkü uzun süre Berlin'de kalacağım."},{"who":"Landlord","en":"It's free from 1 November, and I need your passport and proof of income.","tr":"Daire 1 Kasım'dan itibaren boş; pasaportunuza ve gelir belgenize ihtiyacım var."}],"vocab":[{"en":"bills","tr":"faturalar","ex":"Are the bills included in the rent?"},{"en":"deposit","tr":"depozito","ex":"I need a deposit of three months' rent."},{"en":"pay in instalments","tr":"taksitle ödemek","ex":"Can I pay the deposit in three instalments?"},{"en":"contract","tr":"sözleşme","ex":"The contract is for two years."},{"en":"at least","tr":"en az","ex":"I want to stay for at least two years."},{"en":"proof of income","tr":"gelir belgesi","ex":"I need your passport and proof of income."},{"en":"move in","tr":"taşınmak","ex":"When can I move in?"}],"grammar":{"title":"Comparatives: bigger than, brighter than","tr":"İki şeyi karşılaştırırken kısa sıfatlara -er ekleyip 'than' kullanırız: big → bigger than. Uzun sıfatlarda 'more' kullanırız: more expensive than.","examples":["It's bigger than the photos.","This flat is brighter than my hotel room.","Berlin is more expensive than I thought."]},"questions":[{"q":"What is NOT included in the rent?","options":["Heating","Water","Internet"],"a":2},{"q":"How much is the deposit?","options":["€1,200","€3,600","€2,400"],"a":1},{"q":"How long is the contract?","options":["At least two years","One year","Six months"],"a":0},{"q":"Why is a long contract OK for the speaker?","options":["The rent is cheap","They are going to stay in Berlin for a long time","The flat has a balcony"],"a":1}],"gaps":[{"s":"How much is the rent, and are the ___ included?","a":"bills","hint":"faturalar"},{"s":"It's bigger and brighter ___ the photos.","a":"than","hint":"-den/-dan (karşılaştırma)"},{"s":"The contract is for at ___ two years.","a":"least","hint":"en az"}],"order":[{"a":"I need your passport and proof of income."},{"a":"The contract is for at least two years."}],"translate":[{"tr":"Depozitoyu üç taksitte ödeyebilir miyim?","en":"Can I pay the deposit in three instalments?","keys":["deposit","instalments"]},{"tr":"Uzun süre Berlin'de kalacağım.","en":"I'm going to stay in Berlin for a long time.","keys":["going to stay","long time"]}],"roleplay":{"persona":"Landlord","personaTr":"Ev sahibi","scene":"Daireyi gezdin. Ev sahibi Bayan Becker ne düşündüğünü ve birkaç detayı soruyor.","turns":[{"ai":"So, what do you think of the flat?","aiTr":"Eee, daire hakkında ne düşünüyorsunuz?","hint":"I really like it, and it's bigger than the photos.","keys":["like","bigger","nice"]},{"ai":"Do you have any pets? Cats are OK, but no dogs.","aiTr":"Evcil hayvanınız var mı? Kedi olur ama köpek olmaz.","hint":"No, I don't have any pets, but is the building quiet?","keys":["don't have","pets","quiet"]},{"ai":"Yes, the bedroom is at the back, so it's quiet. Can you send me your documents?","aiTr":"Evet, yatak odası arka tarafta, o yüzden sessiz. Belgelerinizi bana gönderebilir misiniz?","hint":"Sure, I'm going to send my passport and my company papers today.","keys":["passport","company papers","send"]}]}},"ab-02":{"intro":"Berlin'de bankada hesap açıyorsun; adres kaydı, belgeler, şirket hesabı ve ücretler hakkında konuşuyorsun.","text":[{"who":"Clerk","en":"Good morning, how can I help you today?","tr":"Günaydın, bugün size nasıl yardımcı olabilirim?"},{"who":"Me","en":"I want to open an account because I moved to Berlin last month.","tr":"Geçen ay Berlin'e taşındığım için bir hesap açmak istiyorum."},{"who":"Clerk","en":"Did you register your address at the citizens' office?","tr":"Adresinizi Bürgeramt'ta (vatandaşlık bürosunda) kaydettirdiniz mi?"},{"who":"Me","en":"Yes, I registered last week, and here is the certificate.","tr":"Evet, geçen hafta kaydettirdim; belgesi de burada."},{"who":"Clerk","en":"Great, I also need your passport and your residence permit.","tr":"Harika; pasaportunuza ve oturma izninize de ihtiyacım var."},{"who":"Me","en":"I want a business account for my company too.","tr":"Şirketim için de bir ticari hesap istiyorum."},{"who":"Clerk","en":"A business account needs company papers, so we can open it later.","tr":"Ticari hesap için şirket belgeleri gerekiyor, o yüzden onu daha sonra açabiliriz."},{"who":"Clerk","en":"Your debit card and PIN are going to arrive in two separate letters.","tr":"Banka kartınız ve şifreniz iki ayrı mektupla gelecek."},{"who":"Clerk","en":"It's free if you pay in €1,000 a month, but otherwise it's €5.","tr":"Ayda 1.000 avro yatırırsanız ücretsiz, aksi takdirde 5 avro."}],"vocab":[{"en":"register your address","tr":"adresini kaydettirmek","ex":"I registered my address last week."},{"en":"citizens' office","tr":"Bürgeramt, vatandaşlık bürosu","ex":"I went to the citizens' office on Monday."},{"en":"residence permit","tr":"oturma izni","ex":"I need your passport and your residence permit."},{"en":"business account","tr":"ticari hesap, şirket hesabı","ex":"I want a business account for my company."},{"en":"separate","tr":"ayrı","ex":"The PIN comes in a separate letter."},{"en":"pay in","tr":"(hesaba) para yatırmak","ex":"It's free if you pay in €1,000 a month."},{"en":"otherwise","tr":"aksi takdirde, yoksa","ex":"Otherwise it costs €5 a month."}],"grammar":{"title":"Past simple: Did you…? – I registered…","tr":"Geçmişte bitmiş eylemler için past simple kullanırız; düzenli fiillere -ed ekleriz. Soru sorarken 'Did + özne + fiilin yalın hali' kullanırız.","examples":["Did you register your address?","Yes, I registered last week.","I moved to Berlin last month."]},"questions":[{"q":"Where did the speaker register their address?","options":["At the bank","At the citizens' office","At the post office"],"a":1},{"q":"Why can't they open the business account today?","options":["They need company papers first","The bank is closing","It's too expensive"],"a":0},{"q":"How do the card and the PIN arrive?","options":["Together in one letter","By email","In two separate letters"],"a":2},{"q":"How much does the account cost if less than €1,000 comes in?","options":["Nothing","€5 a month","€15 a month"],"a":1}],"gaps":[{"s":"Did you ___ your address at the citizens' office?","a":"register","hint":"kaydettirmek"},{"s":"Your card and PIN are going to arrive in two ___ letters.","a":"separate","hint":"ayrı"},{"s":"It's free if you pay in €1,000 a month, but ___ it's €5.","a":"otherwise","hint":"aksi takdirde"}],"order":[{"a":"I registered my address last week."},{"a":"A business account needs company papers."}],"translate":[{"tr":"Şirketim için bir ticari hesap istiyorum.","en":"I want a business account for my company.","keys":["business account","my company"]},{"tr":"Adresimi geçen hafta kaydettirdim.","en":"I registered my address last week.","keys":["registered","address","last week"]}],"roleplay":{"persona":"Bank clerk","personaTr":"Banka memuru","scene":"Bankadasın. Memur adres kaydını ve internet bankacılığını soruyor.","turns":[{"ai":"Hello! Are you already a customer with us?","aiTr":"Merhaba! Zaten bizim müşterimiz misiniz?","hint":"No, I'm not, but I want to open an account.","keys":["open","account","no"]},{"ai":"Did you register your address in Berlin?","aiTr":"Berlin'de adresinizi kaydettirdiniz mi?","hint":"Yes, I registered last week, and here is the certificate.","keys":["registered","certificate","yes"]},{"ai":"OK. Do you want to use our banking app?","aiTr":"Tamam. Bankacılık uygulamamızı kullanmak ister misiniz?","hint":"Yes, please, because it's easier than going to the bank.","keys":["yes","easier","app"]}]}},"ab-04":{"intro":"Merdivende üst kattaki komşun Lena ile tanışıyorsun, pazartesi de iş arkadaşın Tom'la hafta sonunu konuşuyorsun.","text":[{"who":"Lena","en":"Hi, I'm Lena from upstairs, so you're my new neighbour!","tr":"Merhaba, ben Lena, üst kattan; demek yeni komşum sensin!"},{"who":"Me","en":"Yes, nice to meet you, I'm {name}.","tr":"Evet, tanıştığımıza memnun oldum, ben {name}."},{"who":"Lena","en":"It's cold, but it's nice to see the sun after all that rain.","tr":"Hava soğuk ama onca yağmurdan sonra güneşi görmek güzel."},{"who":"Me","en":"I'm from Istanbul, and I came here to open my startup's European office.","tr":"İstanbulluyum; buraya girişimimin Avrupa ofisini açmak için geldim."},{"who":"Lena","en":"We're going to have a barbecue in the courtyard on Sunday.","tr":"Pazar günü avluda mangal yapacağız."},{"who":"Me","en":"I'd love to come, and I'm going to bring some baklava.","tr":"Gelmeyi çok isterim; biraz baklava getireceğim."},{"who":"Tom","en":"Morning, how was your weekend?","tr":"Günaydın, hafta sonun nasıldı?"},{"who":"Me","en":"It was great because I went to a barbecue with my neighbours.","tr":"Harikaydı, çünkü komşularımla mangala gittim."},{"who":"Tom","en":"Nice, so do you want to come for a drink with us on Friday?","tr":"Güzel; cuma günü bizimle bir şeyler içmeye gelmek ister misin?"}],"vocab":[{"en":"neighbour","tr":"komşu","ex":"You're my new neighbour!"},{"en":"upstairs","tr":"üst kat, üst katta","ex":"I'm Lena from upstairs."},{"en":"courtyard","tr":"avlu","ex":"We're going to have a barbecue in the courtyard."},{"en":"I'd love to","tr":"çok isterim","ex":"I'd love to come on Sunday."},{"en":"How was your weekend?","tr":"Hafta sonun nasıldı?","ex":"Morning, Tom, how was your weekend?"},{"en":"go for a drink","tr":"bir şeyler içmeye gitmek","ex":"Do you want to go for a drink on Friday?"}],"grammar":{"title":"'Going to' for plans","tr":"Önceden planlanmış şeyleri anlatırken 'am/is/are going to + fiil' kullanırız: 'We're going to have a barbecue.'","examples":["We're going to have a barbecue on Sunday.","I'm going to bring some baklava.","Are you going to come on Friday?"]},"questions":[{"q":"Where does Lena live?","options":["On the ground floor","Upstairs","Next door to Tom"],"a":1},{"q":"Why did the speaker come to Berlin?","options":["To study German","To visit friends","To open the startup's European office"],"a":2},{"q":"What is the speaker going to bring to the barbecue?","options":["Baklava","Drinks","A salad"],"a":0},{"q":"What does Tom invite the speaker to?","options":["A barbecue","A drink on Friday","A football match"],"a":1}],"gaps":[{"s":"It's nice to see the ___ after all that rain.","a":"sun","hint":"güneş"},{"s":"We're going to have a barbecue in the ___ on Sunday.","a":"courtyard","hint":"avlu"},{"s":"I'd ___ to come.","a":"love","hint":"çok isterim"}],"order":[{"a":"I went to a barbecue with my neighbours."},{"a":"I'm going to bring some baklava."}],"translate":[{"tr":"Harikaydı, çünkü komşularımla mangala gittim.","en":"It was great because I went to a barbecue with my neighbours.","keys":["went to a barbecue","neighbours"]},{"tr":"Gelmeyi çok isterim.","en":"I'd love to come.","keys":["I'd love to","come"]}],"roleplay":{"persona":"Neighbour (Lena)","personaTr":"Komşu (Lena)","scene":"Cumartesi sabahı merdivende üst kattaki komşun Lena seninle sohbet ediyor.","turns":[{"ai":"Hi, I'm Lena from upstairs! Are you the new neighbour?","aiTr":"Merhaba, ben Lena, üst kattan! Yeni komşu sen misin?","hint":"Yes, I am, and nice to meet you, I'm {name}.","keys":["nice to meet you","yes","I am"]},{"ai":"Welcome! What do you think of Berlin so far?","aiTr":"Hoş geldin! Şimdiye kadar Berlin hakkında ne düşünüyorsun?","hint":"I really like it, because there are so many parks.","keys":["like","parks","because"]},{"ai":"Is it very different from Istanbul?","aiTr":"İstanbul'dan çok farklı mı?","hint":"Yes, the shops are closed on Sundays, and that was a surprise.","keys":["closed on Sundays","surprise","different"]}]}},"ab-03":{"intro":"Doktordan telefonla randevu alıyorsun, sonra muayenede bel ağrını ve uyku sorununu anlatıyorsun.","text":[{"who":"Receptionist","en":"Good morning, Dr Hoffmann's practice, how can I help you?","tr":"Günaydın, Dr. Hoffmann'ın muayenehanesi, size nasıl yardımcı olabilirim?"},{"who":"Me","en":"I'd like to make an appointment because I have back pain.","tr":"Bel ağrım olduğu için randevu almak istiyorum."},{"who":"Receptionist","en":"Our next free appointment is on Thursday at 9:30.","tr":"Bir sonraki boş randevumuz perşembe saat 9.30'da."},{"who":"Receptionist","en":"Please bring your health insurance card with you.","tr":"Lütfen sağlık sigortası kartınızı yanınızda getirin."},{"who":"Doctor","en":"So, what's the problem, and when did it start?","tr":"Evet, sorun nedir ve ne zaman başladı?"},{"who":"Me","en":"My lower back started to hurt three weeks ago.","tr":"Belim üç hafta önce ağrımaya başladı."},{"who":"Me","en":"I work twelve hours a day at my laptop, and I sleep badly too.","tr":"Günde on iki saat dizüstü bilgisayarımın başında çalışıyorum ve ayrıca kötü uyuyorum."},{"who":"Doctor","en":"Your muscles are very tight, but it's nothing serious.","tr":"Kaslarınız çok gergin, ama ciddi bir şey değil."},{"who":"Doctor","en":"Take this prescription to the pharmacy, and try to walk thirty minutes a day.","tr":"Bu reçeteyi eczaneye götürün ve günde otuz dakika yürümeye çalışın."}],"vocab":[{"en":"make an appointment","tr":"randevu almak","ex":"I'd like to make an appointment, please."},{"en":"lower back","tr":"bel","ex":"My lower back hurts."},{"en":"ago","tr":"önce","ex":"It started three weeks ago."},{"en":"tight","tr":"gergin, kasılmış","ex":"Your muscles are very tight."},{"en":"nothing serious","tr":"ciddi bir şey değil","ex":"Don't worry, it's nothing serious."},{"en":"prescription","tr":"reçete","ex":"Take this prescription to the pharmacy."},{"en":"health insurance card","tr":"sağlık sigortası kartı","ex":"Please bring your health insurance card."}],"grammar":{"title":"Past simple + ago","tr":"Bir şeyin geçmişte ne zaman olduğunu söylemek için past simple ve 'ago' kullanırız: 'three weeks ago' = üç hafta önce. Soru: 'When did it start?'","examples":["My lower back started to hurt three weeks ago.","When did it start?","I called the practice two days ago."]},"questions":[{"q":"Why does the speaker call the practice?","options":["To buy medicine","To make an appointment","To cancel a visit"],"a":1},{"q":"When did the pain start?","options":["Three days ago","Three months ago","Three weeks ago"],"a":2},{"q":"What does the doctor say about the muscles?","options":["They are very tight, but it's not serious","They are broken","They are fine"],"a":0},{"q":"What does the doctor tell the speaker to do every day?","options":["Sleep twelve hours","Walk thirty minutes","Work at the laptop"],"a":1}],"gaps":[{"s":"I'd like to make an ___ because I have back pain.","a":"appointment","hint":"randevu"},{"s":"My lower back started to hurt three weeks ___.","a":"ago","hint":"önce"},{"s":"Your muscles are very ___, but it's nothing serious.","a":"tight","hint":"gergin"}],"order":[{"a":"Our next free appointment is on Thursday."},{"a":"Please bring your health insurance card with you."}],"translate":[{"tr":"Belim ağrıdığı için randevu almak istiyorum.","en":"I'd like to make an appointment because my lower back hurts.","keys":["make an appointment","lower back"]},{"tr":"Belim üç hafta önce ağrımaya başladı.","en":"My lower back started to hurt three weeks ago.","keys":["started to hurt","three weeks ago"]}],"roleplay":{"persona":"Doctor","personaTr":"Doktor","scene":"Perşembe sabahı Dr. Hoffmann'ın muayenehanesindesin. Doktor ağrını soruyor.","turns":[{"ai":"Hello, please sit down. What's the problem?","aiTr":"Merhaba, lütfen oturun. Sorun nedir?","hint":"My lower back hurts, and I sleep badly.","keys":["lower back","hurts","sleep badly"]},{"ai":"When did it start?","aiTr":"Ne zaman başladı?","hint":"It started three weeks ago.","keys":["three weeks ago","started"]},{"ai":"Did you take any medicine?","aiTr":"Herhangi bir ilaç aldınız mı?","hint":"Yes, I took ibuprofen, but it only helped for a few hours.","keys":["ibuprofen","took","only helped"]}]}},"li-03":{"intro":"İlk yılda yaptığın hatayı ve şimdi enerjini korumak için uyguladığın üç kuralı anlatıyorsun.","text":[{"who":"Me","en":"In my first year as a founder, I worked fourteen hours a day.","tr":"Kurucu olarak ilk yılımda günde on dört saat çalıştım."},{"who":"Me","en":"I only slept five hours, and I thought it was normal.","tr":"Sadece beş saat uyuyordum ve bunun normal olduğunu düşünüyordum."},{"who":"Me","en":"Then I started to make bad decisions because I was so tired.","tr":"Sonra çok yorgun olduğum için kötü kararlar vermeye başladım."},{"who":"Me","en":"A tired brain chooses the easy answer, not the right one.","tr":"Yorgun bir beyin doğru cevabı değil, kolay cevabı seçer."},{"who":"Me","en":"Now I have three simple rules.","tr":"Şimdi üç basit kuralım var."},{"who":"Me","en":"First, I sleep at least seven hours, with no emails after 10 pm.","tr":"Birincisi, en az yedi saat uyuyorum ve gece 10'dan sonra e-postaya bakmıyorum."},{"who":"Me","en":"Second, I do my most important task in the morning, before meetings.","tr":"İkincisi, en önemli işimi sabah, toplantılardan önce yapıyorum."},{"who":"Me","en":"Third, I walk thirty minutes a day, and that's when my best ideas come.","tr":"Üçüncüsü, günde otuz dakika yürüyorum ve en iyi fikirlerim o zaman geliyor."},{"who":"Me","en":"A startup is a marathon, not a sprint, so I need energy for years.","tr":"Girişim bir sprint değil, maratondur; bu yüzden yıllarca enerjiye ihtiyacım var."}],"vocab":[{"en":"founder","tr":"kurucu","ex":"In my first year as a founder, I worked a lot."},{"en":"make a bad decision","tr":"kötü karar vermek","ex":"I started to make bad decisions."},{"en":"tired","tr":"yorgun","ex":"A tired brain chooses the easy answer."},{"en":"at least","tr":"en az","ex":"I sleep at least seven hours."},{"en":"task","tr":"görev, iş","ex":"I do my most important task in the morning."},{"en":"energy","tr":"enerji","ex":"I need energy for years."},{"en":"a marathon, not a sprint","tr":"sprint değil, maraton","ex":"A startup is a marathon, not a sprint."}],"grammar":{"title":"Past simple vs present simple: then and now","tr":"Geçmişte olup bitmiş durumlar için past simple (worked, slept, thought), bugünkü alışkanlıklar için present simple (sleep, walk) kullanılır. 'Then' ve 'now' iki zamanı karşılaştırmaya yardım eder.","examples":["In my first year, I worked fourteen hours a day.","I only slept five hours.","Now I sleep at least seven hours."]},"questions":[{"q":"How many hours did the founder sleep in the first year?","options":["Seven","Five","Fourteen"],"a":1},{"q":"What was the problem in the first year?","options":["The founder was very tired and made bad decisions","The team was too small","There was no money"],"a":0},{"q":"What does the founder not do after 10 pm?","options":["Walk","Sleep","Read emails"],"a":2},{"q":"When do the founder's best ideas come?","options":["In meetings","During a walk","At night"],"a":1}],"gaps":[{"s":"I started to make bad ___.","a":"decisions","hint":"kararlar"},{"s":"I do my most important ___ in the morning.","a":"task","hint":"görev, iş"},{"s":"A startup is a marathon, not a ___.","a":"sprint","hint":"kısa mesafe koşusu"}],"order":[{"a":"A tired brain chooses the easy answer."},{"a":"Now I have three simple rules."}],"translate":[{"tr":"Kurucu olarak ilk yılımda günde on dört saat çalıştım.","en":"In my first year as a founder, I worked fourteen hours a day.","keys":["first year","fourteen hours"]},{"tr":"Yorgun olduğum için kötü kararlar verdim.","en":"I made bad decisions because I was tired.","keys":["bad decisions","because","tired"]}],"roleplay":{"persona":"Young founder","personaTr":"Genç kurucu","scene":"Genç bir girişimci sürekli çalışıyor ve çok yorgun. Ona deneyimini ve kurallarını anlatıyorsun.","turns":[{"ai":"I work all the time and I am so tired. Is that normal?","aiTr":"Sürekli çalışıyorum ve çok yorgunum. Bu normal mi?","hint":"I thought it was normal too, but a tired brain makes bad decisions.","keys":["tired brain","bad decisions","normal"]},{"ai":"So what did you change?","aiTr":"Peki sen neyi değiştirdin?","hint":"Now I sleep at least seven hours, and I don't read emails after 10 pm.","keys":["at least seven hours","emails","10 pm"]},{"ai":"But when do I do all my work?","aiTr":"Ama bütün işlerimi ne zaman yapacağım?","hint":"Do your most important task in the morning, before your meetings.","keys":["most important task","morning","before"]}]}},"ai-05":{"intro":"Bir hastane alıcısının fiyat, arıza ve deneme sorularına cevap veriyorsun.","text":[{"who":"Buyer","en":"We're interested in your audiometer, so can you tell me the price?","tr":"Odyometrenizle ilgileniyoruz, fiyatını söyleyebilir misiniz?"},{"who":"Me","en":"The device costs 4,000 euros, and the software is 99 euros a month.","tr":"Cihaz 4.000 euro, yazılım da ayda 99 euro."},{"who":"Buyer","en":"That's more expensive than a classic audiometer.","tr":"Bu, klasik bir odyometreden daha pahalı."},{"who":"Me","en":"Yes, but you don't need an expert for every test, so you save money.","tr":"Evet ama her test için bir uzmana ihtiyacınız yok, böylece para tasarrufu yaparsınız."},{"who":"Buyer","en":"What happens if the device breaks?","tr":"Cihaz bozulursa ne olur?"},{"who":"Me","en":"There's a two-year warranty, and we can fix most problems remotely.","tr":"İki yıl garanti var ve çoğu sorunu uzaktan çözebiliyoruz."},{"who":"Buyer","en":"Can we try it before we buy it?","tr":"Satın almadan önce deneyebilir miyiz?"},{"who":"Me","en":"Of course, we can give you a free one-month trial.","tr":"Tabii ki, size bir aylık ücretsiz deneme verebiliriz."}],"vocab":[{"en":"be interested in","tr":"...ile ilgilenmek","ex":"We're interested in your audiometer."},{"en":"cost","tr":"(fiyatı) tutmak","ex":"The device costs 4,000 euros."},{"en":"more expensive than","tr":"...den daha pahalı","ex":"It's more expensive than a classic audiometer."},{"en":"save money","tr":"para tasarrufu yapmak","ex":"You save money because you don't need an expert."},{"en":"break","tr":"bozulmak","ex":"What happens if the device breaks?"},{"en":"warranty","tr":"garanti","ex":"There's a two-year warranty."},{"en":"remotely","tr":"uzaktan","ex":"We can fix most problems remotely."},{"en":"free trial","tr":"ücretsiz deneme","ex":"We can give you a free one-month trial."}],"grammar":{"title":"Comparatives: more expensive than","tr":"İki şeyi karşılaştırırken kısa sıfatlara -er (cheap → cheaper), uzun sıfatlara 'more' (more expensive) ekleriz ve ardından 'than' kullanırız.","examples":["That's more expensive than a classic audiometer.","Our test is faster than a classic test.","In the long run, it is cheaper."]},"questions":[{"q":"How much is the software?","options":["99 euros a month","4,000 euros a year","Nothing"],"a":0},{"q":"Why does the hospital save money?","options":["The device is cheap","They don't need an expert for every test","The software is free"],"a":1},{"q":"What happens if the device breaks?","options":["Nothing can be done","The hospital pays for a new one","It is covered by a two-year warranty"],"a":2},{"q":"What does the founder offer at the end?","options":["A discount","A second device","A lower price","A free one-month trial"],"a":3}],"gaps":[{"s":"We're ___ in your audiometer.","a":"interested","hint":"ilgili"},{"s":"That's more expensive ___ a classic audiometer.","a":"than","hint":"-den (karşılaştırma)"},{"s":"We can fix most problems ___.","a":"remotely","hint":"uzaktan"}],"order":[{"a":"We can give you a free one-month trial."},{"a":"You don't need an expert for every test."}],"translate":[{"tr":"Cihaz bozulursa ne olur?","en":"What happens if the device breaks?","keys":["what happens","breaks"]},{"tr":"Bu, klasik bir odyometreden daha pahalı.","en":"That's more expensive than a classic audiometer.","keys":["more expensive than"]}],"roleplay":{"persona":"Hospital buyer","personaTr":"Hastane satın alma yöneticisi","scene":"Özel bir hastanenin satın alma yöneticisiyle görüşüyorsun; fiyatı pahalı buluyor.","turns":[{"ai":"We like your audiometer. Can you tell me the price?","aiTr":"Odyometrenizi beğendik. Fiyatını söyleyebilir misiniz?","hint":"The device costs 4,000 euros, and the software is 99 euros a month.","keys":["4,000 euros","99 euros","a month","costs"]},{"ai":"Hmm, that's more expensive than other audiometers.","aiTr":"Hmm, bu diğer odyometrelerden daha pahalı.","hint":"Yes, but you don't need an expert for every test, so you save money.","keys":["expert","save money"]},{"ai":"Can we try it before we buy it?","aiTr":"Satın almadan önce deneyebilir miyiz?","hint":"Of course. We can give you a free one-month trial.","keys":["free","trial","of course"]}]}},"li-02":{"intro":"İnsanların neden hayır dediğini ve bir 'hayır'ın nasıl 'evet'e dönüştüğünü anlatıyorsun.","text":[{"who":"Me","en":"When a customer says no, it is usually not about the product.","tr":"Bir müşteri hayır dediğinde, bu genellikle ürünle ilgili değildir."},{"who":"Me","en":"People say no for three reasons: trust, understanding and timing.","tr":"İnsanlar üç nedenle hayır der: güven, anlama ve zamanlama."},{"who":"Me","en":"They need to trust you, so small things are important.","tr":"Size güvenmeleri gerekir, bu yüzden küçük şeyler önemlidir."},{"who":"Me","en":"A quick reply to an email is better than a big office.","tr":"Bir e-postaya hızlı cevap vermek, büyük bir ofisten daha iyidir."},{"who":"Me","en":"They also need to understand you, so I use simple words.","tr":"Sizi anlamaları da gerekir, bu yüzden basit kelimeler kullanırım."},{"who":"Me","en":"People change only when the old way becomes too painful.","tr":"İnsanlar ancak eski yöntem fazla zahmetli hale gelince değişir."},{"who":"Me","en":"Last year, one clinic said no to us.","tr":"Geçen yıl bir klinik bize hayır dedi."},{"who":"Me","en":"Three months later, their waiting list was much longer.","tr":"Üç ay sonra bekleme listeleri çok daha uzundu."},{"who":"Me","en":"We stayed in contact, asked again and got a yes.","tr":"İletişimde kaldık, tekrar sorduk ve bir 'evet' aldık."}],"vocab":[{"en":"reason","tr":"neden, sebep","ex":"People say no for three reasons."},{"en":"trust","tr":"güvenmek, güven","ex":"They need to trust you first."},{"en":"quick reply","tr":"hızlı cevap","ex":"A quick reply to an email builds trust."},{"en":"timing","tr":"zamanlama","ex":"This time the timing was right."},{"en":"painful","tr":"zahmetli, can sıkıcı","ex":"The old way became too painful."},{"en":"waiting list","tr":"bekleme listesi","ex":"Their waiting list was much longer."},{"en":"stay in contact","tr":"iletişimde kalmak","ex":"We stayed in contact with the clinic."}],"grammar":{"title":"Past simple: what happened","tr":"Geçmişte olmuş ve bitmiş olaylar için past simple kullanılır. Düzenli fiillere -ed eklenir (stayed, asked); bazı fiiller düzensizdir (say → said, get → got, is → was).","examples":["Last year, one clinic said no to us.","We stayed in contact and asked again.","Their waiting list was much longer."]},"questions":[{"q":"What is usually NOT the reason for a 'no'?","options":["Trust","Timing","The product"],"a":2},{"q":"What is better than a big office?","options":["A quick reply to an email","A long contract","An expensive website"],"a":0},{"q":"What happened to the clinic's waiting list?","options":["It was shorter","It was much longer","It stopped"],"a":1},{"q":"What did the team do after the first 'no'?","options":["They forgot the clinic","They lowered the price","They stayed in contact"],"a":2}],"gaps":[{"s":"People say no for three ___.","a":"reasons","hint":"nedenler"},{"s":"A quick ___ to an email is better than a big office.","a":"reply","hint":"cevap"},{"s":"Three months later, their waiting ___ was much longer.","a":"list","hint":"liste"}],"order":[{"a":"Last year one clinic said no to us."},{"a":"We stayed in contact and asked again."}],"translate":[{"tr":"Zamanlama sonunda doğruydu.","en":"The timing was finally right.","keys":["timing","right"]},{"tr":"Basit kelimeler kullanırım çünkü insanların beni anlaması gerekir.","en":"I use simple words because people need to understand me.","keys":["simple words","understand"]}],"roleplay":{"persona":"Hesitant clinic owner","personaTr":"Kararsız klinik sahibi","scene":"Klinik sahibi 'şimdi değil' diyor. Gerçek nedeni bulmaya ve kapıyı açık tutmaya çalışıyorsun.","turns":[{"ai":"I like your device, but I don't think we are ready.","aiTr":"Cihazınızı beğendim ama hazır olduğumuzu sanmıyorum.","hint":"I understand. Can I ask what your biggest problem is today?","keys":["understand","biggest problem","ask"]},{"ai":"Our patients wait six weeks for a hearing test, but a new device is a risk.","aiTr":"Hastalarımız işitme testi için altı hafta bekliyor ama yeni bir cihaz risk demek.","hint":"Six weeks is a long time. You can try our device free for one month, so there is no risk.","keys":["try","free","one month","no risk"]},{"ai":"OK, I need to talk to my team first.","aiTr":"Tamam, önce ekibimle konuşmam gerekiyor.","hint":"Of course. I am going to send you a short email next week.","keys":["of course","email","next week"]}]}},"st-04":{"intro":"Bir distribütörle komisyon ve Almanya'daki satış hakları üzerine nazik ama net pazarlık yapıyorsun.","text":[{"who":"Partner","en":"Our usual commission is 25 percent of every device we sell.","tr":"Her zamanki komisyonumuz sattığımız her cihazın yüzde 25'i."},{"who":"Me","en":"Thank you for the offer, but 25 percent is too high for us.","tr":"Teklif için teşekkürler ama yüzde 25 bizim için çok yüksek."},{"who":"Me","en":"Our production costs are high, so we can offer 15 percent.","tr":"Üretim maliyetlerimiz yüksek, bu yüzden yüzde 15 teklif edebiliriz."},{"who":"Partner","en":"That's too low, because we also have marketing costs.","tr":"Bu çok düşük, çünkü bizim de pazarlama masraflarımız var."},{"who":"Me","en":"I understand, so what if we start with 20 percent for the first year?","tr":"Anlıyorum, peki ilk yıl için yüzde 20 ile başlasak nasıl olur?"},{"who":"Me","en":"We can look at the agreement again after twelve months.","tr":"On iki ay sonra anlaşmaya tekrar bakabiliriz."},{"who":"Partner","en":"That sounds fair, but we want exclusive rights in Germany.","tr":"Bu adil görünüyor ama Almanya'da münhasır haklar istiyoruz."},{"who":"Me","en":"That's possible if you reach a minimum sales target.","tr":"Minimum bir satış hedefine ulaşırsanız bu mümkün."},{"who":"Partner","en":"Great, let's put it in writing and sign next week.","tr":"Harika, bunu yazıya dökelim ve gelecek hafta imzalayalım."}],"vocab":[{"en":"commission","tr":"komisyon","ex":"Their usual commission is 25 percent.","def":"a part of the money from each sale that the seller keeps"},{"en":"offer","tr":"teklif, teklif etmek","ex":"Thank you for the offer.","def":"something someone says they will give or do"},{"en":"too high","tr":"çok yüksek","ex":"25 percent is too high for us.","def":"higher than is OK"},{"en":"production costs","tr":"üretim maliyetleri","ex":"Our production costs are high.","def":"the money you spend to make a product"},{"en":"what if we...?","tr":"...sak nasıl olur?","ex":"What if we start with 20 percent?","def":"a polite way to suggest something"},{"en":"exclusive rights","tr":"münhasır haklar (tek satıcılık)","ex":"They want exclusive rights in Germany.","def":"the right to be the only seller in a place"},{"en":"sales target","tr":"satış hedefi","ex":"You need to reach a minimum sales target.","def":"the number of products you plan to sell"},{"en":"put it in writing","tr":"yazıya dökmek","ex":"Let's put it in writing.","def":"to write an agreement down on paper"}],"grammar":{"title":"Too + adjective","tr":"'Too' bir şeyin gereğinden fazla olduğunu ve sorun yarattığını gösterir: 'too high' (fazla yüksek), 'too low' (fazla düşük). Daha nazik olmak için 'a bit too high' diyebilirsin.","examples":["25 percent is too high for us.","That's too low."]},"questions":[{"q":"What commission does the distributor want first?","options":["15 percent","20 percent","25 percent"],"a":2},{"q":"Why can the speaker only offer 15 percent?","options":["Production costs are high","They don't like the distributor","The device is cheap"],"a":0},{"q":"What does the speaker suggest for the first year?","options":["15 percent","20 percent","25 percent"],"a":1},{"q":"What must the distributor do to get exclusive rights?","options":["Pay more money","Open an office","Reach a minimum sales target"],"a":2}],"gaps":[{"s":"Thank you for the ___, but 25 percent is too high.","a":"offer","hint":"teklif"},{"s":"That's possible if you reach a minimum sales ___.","a":"target","hint":"hedef"},{"s":"Let's put it in ___ and sign next week.","a":"writing","hint":"yazı"}],"order":[{"a":"What if we start with 20 percent?"},{"a":"We can look at the agreement again."}],"translate":[{"tr":"Teklif için teşekkürler.","en":"Thank you for the offer.","keys":["thank you","offer"]},{"tr":"Bu kulağa adil geliyor.","en":"That sounds fair.","keys":["sounds fair"]}],"roleplay":{"persona":"Distributor","personaTr":"Distribütör","scene":"Almanya'da satış yapmak isteyen Hollandalı bir distribütörle komisyon oranı ve münhasırlık konusunda pazarlık yapıyorsun.","turns":[{"ai":"Our usual commission is 25 percent. Is that OK for you?","aiTr":"Her zamanki komisyonumuz yüzde 25. Sizin için uygun mu?","hint":"Thank you for the offer, but 25 percent is too high. We can offer 15 percent.","keys":["too high","offer","15"]},{"ai":"Fifteen is too low. We also have marketing costs.","aiTr":"On beş çok düşük. Bizim de pazarlama masraflarımız var.","hint":"I understand. What if we start with 20 percent for the first year?","keys":["what if","20","first year"]},{"ai":"OK, that sounds fair. We also want exclusive rights in Germany.","aiTr":"Tamam, adil görünüyor. Almanya'da münhasır haklar da istiyoruz.","hint":"That's possible if you reach a minimum sales target.","keys":["possible","sales target","if you reach"]}]}},"st-05":{"intro":"Bir hastane şikayetle arıyor; özür diliyor, sorunu anlıyor ve çözüyorsun.","text":[{"en":"Yesterday, a hospital in Izmir called us with a problem.","tr":"Dün İzmir'deki bir hastane bizi bir sorunla aradı."},{"en":"Our device stopped working in the middle of a hearing test.","tr":"Cihazımız bir işitme testinin ortasında çalışmayı durdurdu."},{"en":"The doctor was angry because she had a lot of patients waiting.","tr":"Doktor kızgındı çünkü bekleyen çok hastası vardı."},{"en":"First, I said sorry and thanked her for calling so quickly.","tr":"Önce özür diledim ve bu kadar hızlı aradığı için ona teşekkür ettim."},{"en":"Then I asked some questions to understand the problem.","tr":"Sonra sorunu anlamak için birkaç soru sordum."},{"en":"It was a software bug, not a problem with the hardware.","tr":"Bu bir yazılım hatasıydı, donanımla ilgili bir sorun değildi."},{"en":"Our engineer sent an update, and two hours later the device worked again.","tr":"Mühendisimiz bir güncelleme gönderdi ve iki saat sonra cihaz yeniden çalıştı."},{"en":"After that, I called the doctor back to check that everything was fine.","tr":"Ardından her şeyin yolunda olup olmadığını kontrol etmek için doktoru geri aradım."},{"en":"A good answer to a problem can make a customer trust you more.","tr":"Bir soruna iyi bir yanıt vermek, müşterinin size daha çok güvenmesini sağlayabilir."}],"vocab":[{"en":"stop working","tr":"çalışmayı durdurmak, bozulmak","ex":"Our device stopped working during a test."},{"en":"say sorry","tr":"özür dilemek","ex":"First, I said sorry to the doctor."},{"en":"software bug","tr":"yazılım hatası","ex":"It was a software bug."},{"en":"hardware","tr":"donanım","ex":"There was no problem with the hardware."},{"en":"send an update","tr":"güncelleme göndermek","ex":"Our engineer sent an update."},{"en":"call someone back","tr":"birini geri aramak","ex":"I called the doctor back."},{"en":"trust","tr":"güvenmek","ex":"Good service makes customers trust you."}],"grammar":{"title":"Past simple: what happened yesterday","tr":"Dün olan bir olayı anlatırken past simple kullanılır. Düzenli fiillere -ed eklenir (called, stopped); bazı fiiller düzensizdir (send → sent, say → said).","examples":["A hospital called us.","The device stopped working.","Our engineer sent an update."]},"questions":[{"q":"Why was the doctor angry?","options":["The device was too expensive","She had a lot of patients waiting","Nobody answered the phone"],"a":1},{"q":"What did the speaker do first?","options":["Said sorry and thanked her","Sent an engineer to Izmir","Asked for money"],"a":0},{"q":"What kind of problem was it?","options":["A hardware problem","A problem with the headphones","A software bug"],"a":2},{"q":"What happened two hours later?","options":["The doctor called again","The device worked again","The hospital sent the device back"],"a":1}],"gaps":[{"s":"Our device stopped ___ in the middle of a test.","a":"working","hint":"çalışmak"},{"s":"It was a software ___, not a problem with the hardware.","a":"bug","hint":"hata"},{"s":"I called the doctor ___ to check that everything was fine.","a":"back","hint":"geri"}],"order":[{"a":"Then I asked some questions to understand the problem."},{"a":"Our engineer sent an update."}],"translate":[{"tr":"Sorun için özür dilerim.","en":"I'm sorry about the problem.","keys":["sorry","problem"]},{"tr":"Sizi iki saat içinde geri arayacağım.","en":"I will call you back in two hours.","keys":["call you back","two hours"]}],"roleplay":{"persona":"Angry doctor","personaTr":"Kızgın doktor","scene":"İzmir'deki bir hastanenin doktoru arıyor: cihaz testin ortasında durdu ve bekleyen hastalar var.","turns":[{"ai":"Hello? Your device stopped in the middle of a test!","aiTr":"Alo? Cihazınız bir testin ortasında durdu!","hint":"I'm really sorry about that. Thank you for calling so quickly.","keys":["sorry","thank you"]},{"ai":"The screen is black and it doesn't start again.","aiTr":"Ekran siyah ve tekrar açılmıyor.","hint":"I think it's a software bug. Our engineer can send an update.","keys":["software","bug","update"]},{"ai":"How long will it take? I have ten patients waiting.","aiTr":"Ne kadar sürecek? Bekleyen on hastam var.","hint":"About two hours. I'll call you back to check that everything is fine.","keys":["two hours","call you back","check"]}]}},"co-03":{"intro":"Ortağın fiyatı düşürmek istiyor. Sen 'ama' ve 'çünkü' ile nedenini açıklayarak nazikçe karşı çıkıyorsun.","text":[{"who":"Partner","en":"I want to lower the price to 2,000 euros so we sell faster.","tr":"Daha hızlı satalım diye fiyatı 2.000 euroya düşürmek istiyorum."},{"who":"Me","en":"I understand, but I'm not sure that's the best idea.","tr":"Anlıyorum ama bunun en iyi fikir olduğundan emin değilim."},{"who":"Me","en":"The device costs 1,500 euros to make.","tr":"Cihazın üretimi 1.500 euroya mal oluyor."},{"who":"Me","en":"At 2,000 euros, our margin is going to be too small.","tr":"2.000 euroda kâr marjımız çok küçük olacak."},{"who":"Partner","en":"But customers told us the device is too expensive.","tr":"Ama müşteriler bize cihazın çok pahalı olduğunu söyledi."},{"who":"Me","en":"That's true, but we need to show them how much they save every month.","tr":"Doğru ama onlara her ay ne kadar tasarruf ettiklerini göstermemiz gerekiyor."},{"who":"Partner","en":"Good point, but how can we do that?","tr":"Haklısın ama bunu nasıl yapabiliriz?"},{"who":"Me","en":"We can make a simple calculator that shows the savings.","tr":"Tasarrufu gösteren basit bir hesaplayıcı yapabiliriz."},{"who":"Partner","en":"OK, let's try it for two months before we change the price.","tr":"Tamam, fiyatı değiştirmeden önce bunu iki ay deneyelim."}],"vocab":[{"en":"lower the price","tr":"fiyatı düşürmek","ex":"I want to lower the price to sell faster."},{"en":"I'm not sure","tr":"emin değilim","ex":"I'm not sure that's the best idea."},{"en":"margin","tr":"kâr marjı","ex":"At 2,000 euros, our margin is going to be too small."},{"en":"That's true, but...","tr":"Doğru ama...","ex":"That's true, but we need to show them the savings."},{"en":"save","tr":"tasarruf etmek","ex":"Clinics save money every month."},{"en":"Good point.","tr":"Haklısın. / İyi bir nokta.","ex":"Good point, but how can we do that?"},{"en":"calculator","tr":"hesaplayıcı, hesap aracı","ex":"We can make a simple calculator."}],"grammar":{"title":"want to / need to + verb","tr":"'want to' bir şeyi yapmak istediğini, 'need to' bir şeyi yapmanın gerekli olduğunu anlatır. İkisinden sonra fiilin yalın hali gelir.","examples":["I want to lower the price.","We need to show them the savings.","Do you want to try it for two months?"]},"questions":[{"q":"Why does the partner want a lower price?","options":["To sell faster","To make the device better","Because the device costs less now"],"a":0},{"q":"How much does the device cost to make?","options":["2,000 euros","4,000 euros","1,500 euros"],"a":2},{"q":"What does the speaker want to show customers?","options":["A new device","How much money they save","The team"],"a":1},{"q":"How long are they going to try the calculator?","options":["Two weeks","Two months","One year"],"a":1}],"gaps":[{"s":"I want to ___ the price to 2,000 euros.","a":"lower","hint":"düşürmek"},{"s":"At 2,000 euros, our ___ is going to be too small.","a":"margin","hint":"kâr marjı"},{"s":"We need to ___ them how much they save.","a":"show","hint":"göstermek"}],"order":[{"a":"I'm not sure that's the best idea."},{"a":"We can make a simple calculator."}],"translate":[{"tr":"Fiyatı düşürmek istiyorum.","en":"I want to lower the price.","keys":["want to","lower the price"]},{"tr":"Bunun en iyi fikir olduğundan emin değilim.","en":"I'm not sure that's the best idea.","keys":["not sure","best idea"]}],"roleplay":{"persona":"Business partner","personaTr":"İş ortağı","scene":"Ortağın cihazı ücretsiz verip sadece yazılımı satmak istiyor; sen nazikçe karşı çıkıyorsun.","turns":[{"ai":"I want to give the device away for free and only sell the software.","aiTr":"Cihazı ücretsiz verip sadece yazılımı satmak istiyorum.","hint":"I understand, but I'm not sure that's a good idea. The device costs us 1,500 euros.","keys":["not sure","costs","understand"]},{"ai":"But customers are going to love a free device!","aiTr":"Ama müşteriler ücretsiz bir cihaza bayılacak!","hint":"That's true, but then we need to charge more for the software.","keys":["that's true","charge more","software"]},{"ai":"OK, good point. So what do you want to do?","aiTr":"Tamam, haklısın. Peki ne yapmak istiyorsun?","hint":"Let's try both ideas with a few clinics for two months.","keys":["try","both","two months"]}]}},"in-01":{"intro":"Üç dakikalık bir sunumda girişimini, sorunu ve çözümü anlatıyorsun.","text":[{"who":"Me","en":"Hello everyone, my name is {name}, and I'm the founder of AIHEAR.","tr":"Herkese merhaba, benim adım {name} ve AIHEAR'ın kurucusuyum."},{"who":"Me","en":"One in five people has hearing loss, but most are never tested.","tr":"Her beş kişiden biri işitme kaybı yaşıyor, ama çoğu hiç test edilmiyor."},{"who":"Me","en":"That's because there aren't enough hearing experts, so people wait for months.","tr":"Bunun nedeni yeterince işitme uzmanı olmaması, bu yüzden insanlar aylarca bekliyor."},{"who":"Me","en":"Our solution is a smart device that tests hearing without an expert.","tr":"Çözümümüz, işitmeyi uzman olmadan test eden akıllı bir cihaz."},{"who":"Me","en":"The test is fully automatic and takes less than ten minutes.","tr":"Test tamamen otomatik ve on dakikadan kısa sürüyor."},{"who":"Me","en":"We sell the device and charge clinics a monthly fee for the software.","tr":"Cihazı satıyoruz ve kliniklerden yazılım için aylık bir ücret alıyoruz."},{"who":"Me","en":"We already have five paying customers and a team of six people.","tr":"Şimdiden beş ödeme yapan müşterimiz ve altı kişilik bir ekibimiz var."},{"who":"Me","en":"We're raising 500,000 euros to get certified and enter the European market.","tr":"Sertifika almak ve Avrupa pazarına girmek için 500.000 euro yatırım topluyoruz."},{"who":"Me","en":"Thank you, and I'm happy to answer your questions.","tr":"Teşekkürler, sorularınızı yanıtlamaktan memnuniyet duyarım."}],"vocab":[{"en":"founder","tr":"kurucu","ex":"I'm the founder of AIHEAR."},{"en":"hearing loss","tr":"işitme kaybı","ex":"Most people with hearing loss are never tested."},{"en":"solution","tr":"çözüm","ex":"Our solution is a smart device."},{"en":"charge a fee","tr":"ücret almak","ex":"We charge clinics a monthly fee."},{"en":"paying customer","tr":"ödeme yapan müşteri","ex":"We have five paying customers."},{"en":"raise money","tr":"yatırım toplamak","ex":"We want to raise 500,000 euros."},{"en":"enter the market","tr":"pazara girmek","ex":"We want to enter the European market."}],"grammar":{"title":"Linking ideas: but, because, so","tr":"'But' zıtlık, 'because' sebep, 'so' sonuç bildirir. Kısa bir sunumda fikirleri bu üç kelimeyle bağlamak konuşmanı akıcı yapar.","examples":["One in five people has hearing loss, but most are never tested.","That's because there aren't enough hearing experts.","There aren't enough experts, so people wait for months."]},"questions":[{"q":"Why are most people never tested?","options":["The test is too expensive","There aren't enough hearing experts","They don't want to know"],"a":1},{"q":"How long does the test take?","options":["Less than ten minutes","About an hour","Two days"],"a":0},{"q":"How does the company make money?","options":["From advertising","From the government","It sells the device and charges a monthly fee"],"a":2},{"q":"What is the 500,000 euros for?","options":["A new office","Certification and the European market","Free devices for hospitals"],"a":1}],"gaps":[{"s":"Our ___ is a smart device that tests hearing.","a":"solution","hint":"çözüm"},{"s":"We ___ clinics a monthly fee for the software.","a":"charge","hint":"ücret alıyoruz"},{"s":"We want to ___ 500,000 euros.","a":"raise","hint":"toplamak"}],"order":[{"a":"The test is fully automatic and takes less than ten minutes."},{"a":"We already have five paying customers."}],"translate":[{"tr":"Çoğu insan hiç test edilmiyor.","en":"Most people are never tested.","keys":["never tested"]},{"tr":"Pazara girmek istiyoruz.","en":"We want to enter the market.","keys":["want to","enter the market"]}],"roleplay":{"persona":"Investor at a demo day","personaTr":"Demo günü yatırımcısı","scene":"Sunumun bitti. Yatırımcı üç soru soruyor.","turns":[{"ai":"Nice pitch! What problem do you solve?","aiTr":"Güzel sunum! Hangi sorunu çözüyorsunuz?","hint":"One in five people has hearing loss, but most are never tested.","keys":["hearing loss","never tested","one in five"]},{"ai":"How do you make money?","aiTr":"Nasıl para kazanıyorsunuz?","hint":"We sell the device and charge a monthly fee for the software.","keys":["sell the device","monthly fee","charge"]},{"ai":"How much do you want to raise?","aiTr":"Ne kadar yatırım toplamak istiyorsunuz?","hint":"We want to raise 500,000 euros to get certified and enter the European market.","keys":["500,000","certified","European market"]}]}},"ai-03":{"intro":"Prototipini, geçmiş adımları ve sonraki planı basit cümlelerle sunuyorsun.","text":[{"en":"Thank you for your time; let me show you our prototype.","tr":"Zamanınız için teşekkürler; size prototipimizi göstereyim."},{"en":"We are building an AI-assisted audiometer that makes hearing tests faster and easier.","tr":"İşitme testlerini daha hızlı ve daha kolay hâle getiren, yapay zekâ destekli bir odyometre geliştiriyoruz."},{"en":"This is the third version of the prototype.","tr":"Bu, prototipin üçüncü versiyonu."},{"en":"The first one was just a laptop and a pair of headphones.","tr":"İlki sadece bir dizüstü bilgisayar ve bir kulaklıktı."},{"en":"The main development work is now finished.","tr":"Ana geliştirme çalışması artık bitti."},{"en":"Last spring, we published a study with 200 people at two university hospitals.","tr":"Geçen bahar iki üniversite hastanesinde 200 kişiyle yapılan bir çalışma yayımladık."},{"en":"Our results matched a trained audiologist in 94% of cases.","tr":"Sonuçlarımız, vakaların %94'ünde eğitimli bir odyologla eşleşti."},{"en":"Now we need to get the CE mark so we can sell in Europe.","tr":"Şimdi Avrupa'da satış yapabilmek için CE işaretini almamız gerekiyor."},{"en":"We are raising €500,000 to finish certification by the end of next year.","tr":"Sertifikasyonu gelecek yılın sonuna kadar bitirmek için 500.000 € yatırım topluyoruz."}],"vocab":[{"en":"prototype","tr":"prototip","ex":"Let me show you our prototype."},{"en":"AI-assisted","tr":"yapay zekâ destekli","ex":"We are building an AI-assisted audiometer."},{"en":"version","tr":"versiyon, sürüm","ex":"This is the third version."},{"en":"a pair of headphones","tr":"bir kulaklık","ex":"The first one was a laptop and a pair of headphones."},{"en":"publish a study","tr":"bir çalışma yayımlamak","ex":"We published a study last spring."},{"en":"match","tr":"eşleşmek, uyuşmak","ex":"Our results matched a trained audiologist."},{"en":"CE mark","tr":"CE işareti","ex":"We need the CE mark to sell in Europe."},{"en":"raise money","tr":"yatırım toplamak","ex":"We are raising €500,000."}],"grammar":{"title":"Past simple: what we did","tr":"Geçmişte bitmiş olaylar için past simple kullanılır: was, published, matched. Sunumda geçmiş başarıları anlatmak için çok kullanışlıdır.","examples":["The first one was just a laptop.","We published a study last spring.","Our results matched a trained audiologist."]},"questions":[{"q":"Which version of the prototype is this?","options":["The first","The second","The third"],"a":2},{"q":"What was the first prototype?","options":["A laptop and headphones","A phone app","A big machine"],"a":0},{"q":"How many people were in the study?","options":["20","200","2,000"],"a":1},{"q":"Why does the company need the CE mark?","options":["To sell in Europe","To open a factory","To hire engineers"],"a":0}],"gaps":[{"s":"Let me show you our ___.","a":"prototype","hint":"prototip"},{"s":"The first one was just a laptop and a ___ of headphones.","a":"pair","hint":"çift"},{"s":"We are ___ €500,000 to finish certification.","a":"raising","hint":"toplamak"}],"order":[{"a":"This is the third version of the prototype."},{"a":"We need to get the CE mark."}],"translate":[{"tr":"Sonuçlarımız bir odyologla eşleşti.","en":"Our results matched an audiologist.","keys":["results","matched"]},{"tr":"Avrupa'da satış yapmak istiyoruz.","en":"We want to sell in Europe.","keys":["sell","Europe"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Londra'da bir sağlık teknolojisi yatırımcısı prototipini görmek istiyor.","turns":[{"ai":"Thanks for coming. What are you building?","aiTr":"Geldiğiniz için teşekkürler. Ne geliştiriyorsunuz?","hint":"We are building an AI-assisted audiometer that makes hearing tests faster and easier.","keys":["audiometer","faster","easier"]},{"ai":"Do you have any results from real people?","aiTr":"Gerçek insanlardan sonuçlarınız var mı?","hint":"Yes, we tested 200 people, and our results matched an audiologist in 94% of cases.","keys":["200","94","matched"]},{"ai":"And what do you need the money for?","aiTr":"Peki paraya ne için ihtiyacınız var?","hint":"We need to get the CE mark so we can sell in Europe.","keys":["CE mark","sell in Europe","certification"]}]}},"in-02":{"intro":"Bir yatırımcıya gelir kaynaklarınızı ve maliyetlerinizi anlatıyorsun.","text":[{"who":"Me","en":"Investors always ask the same question: how do you make money?","tr":"Yatırımcılar hep aynı soruyu sorar: Nasıl para kazanıyorsunuz?"},{"who":"Me","en":"We have two sources of income: the device and the software.","tr":"İki gelir kaynağımız var: cihaz ve yazılım."},{"who":"Me","en":"The device sells for 4,000 euros and costs 1,500 to make.","tr":"Cihaz 4.000 euroya satılıyor ve üretimi 1.500 euroya mal oluyor."},{"who":"Me","en":"So we keep about 60 percent of every sale.","tr":"Yani her satışın yaklaşık yüzde 60'ı bize kalıyor."},{"who":"Me","en":"Clinics also pay 99 euros a month to use our software.","tr":"Klinikler ayrıca yazılımımızı kullanmak için ayda 99 euro ödüyor."},{"who":"Me","en":"This money comes in every month, so it's easier to plan.","tr":"Bu para her ay geliyor, bu yüzden plan yapmak daha kolay."},{"who":"Me","en":"With 1,000 clinics, that's about 1.2 million euros a year.","tr":"1.000 klinikle bu, yılda yaklaşık 1,2 milyon euro eder."},{"who":"Me","en":"Our biggest costs are salaries, certification and marketing.","tr":"En büyük maliyetlerimiz maaşlar, sertifikasyon ve pazarlama."},{"who":"Me","en":"We think we're going to make a profit in our third year.","tr":"Üçüncü yılımızda kâr edeceğimizi düşünüyoruz."}],"vocab":[{"en":"make money","tr":"para kazanmak","ex":"How do you make money?"},{"en":"income","tr":"gelir","ex":"We have two sources of income."},{"en":"cost (to make)","tr":"üretimi ... mal olmak","ex":"It costs 1,500 euros to make."},{"en":"a month","tr":"ayda","ex":"Clinics pay 99 euros a month."},{"en":"come in","tr":"(para) gelmek","ex":"This money comes in every month."},{"en":"biggest cost","tr":"en büyük maliyet","ex":"Salaries are our biggest cost."},{"en":"make a profit","tr":"kâr etmek","ex":"We're going to make a profit in our third year."}],"grammar":{"title":"Going to: plans and predictions","tr":"'be going to + fiil' gelecekle ilgili planlar ve elimizdeki bilgilere dayanan tahminler için kullanılır.","examples":["We're going to make a profit in our third year.","We're going to sell more devices next year.","Are you going to raise money?"]},"questions":[{"q":"How many sources of income are there?","options":["One","Two","Three"],"a":1},{"q":"How much does it cost to make the device?","options":["1,500 euros","4,000 euros","99 euros"],"a":0},{"q":"Why is monthly money good?","options":["It is tax-free","It comes from investors","It is easier to plan"],"a":2},{"q":"When do they think they will make a profit?","options":["In the first year","In the third year","Never"],"a":1}],"gaps":[{"s":"We have two sources of ___.","a":"income","hint":"gelir"},{"s":"Clinics pay 99 euros a ___ to use our software.","a":"month","hint":"ay"},{"s":"Our biggest ___ are salaries, certification and marketing.","a":"costs","hint":"maliyetler"}],"order":[{"a":"We keep about 60 percent of every sale."},{"a":"Clinics pay 99 euros a month."}],"translate":[{"tr":"İki gelir kaynağımız var.","en":"We have two sources of income.","keys":["two sources","income"]},{"tr":"Üçüncü yılımızda kâr edeceğiz.","en":"We're going to make a profit in our third year.","keys":["make a profit","third year"]}],"roleplay":{"persona":"Angel investor","personaTr":"Melek yatırımcı","scene":"Bir melek yatırımcı rakamlarınızı soruyor.","turns":[{"ai":"So, how do you make money?","aiTr":"Peki, nasıl para kazanıyorsunuz?","hint":"We have two sources of income: the device and a monthly software fee.","keys":["two sources","device","software"]},{"ai":"How much does the device cost to make?","aiTr":"Cihazın üretim maliyeti ne kadar?","hint":"It costs 1,500 euros to make, and we sell it for 4,000.","keys":["1,500","4,000","costs"]},{"ai":"When are you going to make a profit?","aiTr":"Ne zaman kâr edeceksiniz?","hint":"We think we're going to make a profit in our third year.","keys":["third year","make a profit"]}]}},"in-04":{"intro":"Yatırımcının rakipler, kopyalanma ve risk sorularına net cevaplar veriyorsun.","text":[{"who":"Investor","en":"Who are your competitors, and why are you better?","tr":"Rakipleriniz kimler ve neden daha iyisiniz?"},{"who":"Me","en":"Big companies make classic audiometers, but you need an expert to use them.","tr":"Büyük şirketler klasik odyometreler yapıyor ama onları kullanmak için bir uzmana ihtiyacınız var."},{"who":"Me","en":"There are some hearing apps too, but they aren't certified medical devices.","tr":"Bazı işitme uygulamaları da var ama bunlar sertifikalı tıbbi cihazlar değil."},{"who":"Investor","en":"What stops a big company from copying you?","tr":"Büyük bir şirketin sizi kopyalamasını ne engelliyor?"},{"who":"Me","en":"We trained our AI on thousands of real tests, so it's hard to copy.","tr":"Yapay zekâmızı binlerce gerçek testle eğittik, bu yüzden onu kopyalamak zor."},{"who":"Me","en":"Also, big companies are slower than small teams like ours.","tr":"Ayrıca büyük şirketler bizimki gibi küçük ekiplerden daha yavaş."},{"who":"Investor","en":"What is the biggest risk for your company?","tr":"Şirketiniz için en büyük risk ne?"},{"who":"Me","en":"Honestly, certification can take longer than we planned.","tr":"Açıkçası sertifikasyon planladığımızdan uzun sürebilir."},{"who":"Me","en":"So we started the process early, and we're working with an experienced consultant.","tr":"Bu yüzden sürece erken başladık ve deneyimli bir danışmanla çalışıyoruz."}],"vocab":[{"en":"competitor","tr":"rakip","ex":"Who are your main competitors?"},{"en":"certified","tr":"sertifikalı","ex":"The apps aren't certified medical devices."},{"en":"copy","tr":"kopyalamak","ex":"It is hard to copy our AI."},{"en":"train an AI on","tr":"yapay zekâyı ... ile eğitmek","ex":"We trained our AI on thousands of real tests."},{"en":"slower than","tr":"...den daha yavaş","ex":"Big companies are slower than small teams."},{"en":"take longer than","tr":"...den daha uzun sürmek","ex":"Certification can take longer than we planned."},{"en":"honestly","tr":"açıkçası, dürüst olmak gerekirse","ex":"Honestly, certification is our biggest risk."},{"en":"experienced consultant","tr":"deneyimli danışman","ex":"We're working with an experienced consultant."}],"grammar":{"title":"Comparatives: slower, longer, better","tr":"İki şeyi karşılaştırmak için kısa sıfatlara -er eklenir ve ardından 'than' gelir: slow → slower than. Bazı sıfatlar düzensizdir: good → better.","examples":["Big companies are slower than small teams.","Certification can take longer than we planned.","Why are you better?"]},"questions":[{"q":"What is the problem with classic audiometers?","options":["They are too small","You need an expert to use them","They are not for sale"],"a":1},{"q":"Why are the apps not real competitors?","options":["They aren't certified medical devices","They are too expensive","They only work in Turkey"],"a":0},{"q":"Why is the company hard to copy?","options":["It has a big office","It has a lot of money","Its AI learned from thousands of real tests"],"a":2},{"q":"What did the company do about the certification risk?","options":["It stopped the process","It started early and works with a consultant","It moved to the US"],"a":1}],"gaps":[{"s":"There are some apps too, but they aren't ___ medical devices.","a":"certified","hint":"sertifikalı"},{"s":"Big companies are ___ than small teams like ours.","a":"slower","hint":"daha yavaş"},{"s":"Certification can take ___ than we planned.","a":"longer","hint":"daha uzun"}],"order":[{"a":"What stops a big company from copying you?"},{"a":"Certification can take longer than we planned."}],"translate":[{"tr":"Biz büyük şirketlerden daha hızlıyız.","en":"We are faster than big companies.","keys":["faster than","big companies"]},{"tr":"Deneyimli bir danışmanla çalışıyoruz.","en":"We're working with an experienced consultant.","keys":["experienced consultant"]}],"roleplay":{"persona":"Tough investor","personaTr":"Sert yatırımcı","scene":"Deneyimli bir yatırımcı zor sorular soruyor; sakin ve net cevap ver.","turns":[{"ai":"Who are your competitors?","aiTr":"Rakipleriniz kimler?","hint":"Big companies make classic audiometers, but you need an expert to use them.","keys":["audiometers","expert","big companies"]},{"ai":"A big company can copy you. What then?","aiTr":"Büyük bir şirket sizi kopyalayabilir. O zaman ne olacak?","hint":"We trained our AI on thousands of real tests, so it is hard to copy. And we are faster.","keys":["trained","real tests","hard to copy","faster"]},{"ai":"What is your biggest risk?","aiTr":"En büyük riskiniz ne?","hint":"Honestly, certification can take longer than we planned, so we started early.","keys":["honestly","certification","longer","started early"]}]}},"fu-02":{"intro":"Bir gazeteci seninle sağlık verilerinin etiği hakkında röportaj yapıyor; verinin kime ait olduğunu ve şirketinin veriyi nasıl koruduğunu anlatıyorsun.","text":[{"who":"Journalist","en":"Who should own a patient's health data?","tr":"Bir hastanın sağlık verileri kime ait olmalı?"},{"who":"Me","en":"The patient, because it is information about their body and their life.","tr":"Hastaya, çünkü bunlar onun bedeni ve hayatı hakkında bilgiler."},{"who":"Me","en":"Patients need to know how we use their data, and they need to agree.","tr":"Hastaların verilerini nasıl kullandığımızı bilmeleri ve buna onay vermeleri gerekir."},{"who":"Me","en":"For research, we remove names, so nobody knows who the patient is.","tr":"Araştırma için isimleri siliyoruz, böylece kimse hastanın kim olduğunu bilmiyor."},{"who":"Me","en":"In Europe, a law called GDPR protects health data.","tr":"Avrupa'da GDPR adlı bir yasa sağlık verilerini koruyor."},{"who":"Me","en":"Our AI runs on the device, so the test data stays in the clinic.","tr":"Yapay zekâmız cihazın üzerinde çalışıyor, bu yüzden test verileri klinikte kalıyor."},{"who":"Journalist","en":"But doesn't AI need more data to get better?","tr":"Ama yapay zekânın gelişmek için daha fazla veriye ihtiyacı yok mu?"},{"who":"Me","en":"Yes, more data makes AI smarter, but it is also a bigger risk.","tr":"Evet, daha fazla veri yapay zekâyı daha akıllı yapar ama aynı zamanda daha büyük bir risktir."},{"who":"Me","en":"We only use anonymous data from people who agreed, because privacy comes first.","tr":"Sadece onay veren kişilerin anonim verilerini kullanıyoruz, çünkü önce gizlilik gelir."}],"vocab":[{"en":"own","tr":"sahip olmak","ex":"Patients should own their health data."},{"en":"agree","tr":"onay vermek, kabul etmek","ex":"Patients need to agree first."},{"en":"remove","tr":"silmek, çıkarmak","ex":"We remove names for research."},{"en":"law","tr":"yasa, kanun","ex":"GDPR is a European law."},{"en":"protect","tr":"korumak","ex":"GDPR protects health data."},{"en":"risk","tr":"risk","ex":"More data is also a bigger risk."},{"en":"anonymous","tr":"anonim, isimsiz","ex":"We only use anonymous data."},{"en":"come first","tr":"önce gelmek","ex":"Privacy comes first for us."}],"grammar":{"title":"need to: what is necessary","tr":"'Need to + fiil' bir şeyin gerekli olduğunu anlatır: Patients need to know, they need to agree. Olumsuz biçim: 'don't need to'. Soru biçimi: 'Does AI need…?' ya da 'Doesn't AI need…?'","examples":["Patients need to know how we use their data.","They need to agree.","Doesn't AI need more data to get better?"]},"questions":[{"q":"Why should the patient own the data?","options":["Because it is about their body and life","Because the company says so","Because the data is cheap"],"a":0},{"q":"What does the company remove for research?","options":["The test results","The devices","Names"],"a":2},{"q":"What is GDPR?","options":["A hearing test","A European law that protects data","A software update"],"a":1},{"q":"What is the problem with more data?","options":["It is too slow","It costs nothing","It is illegal","It is a bigger risk"],"a":3}],"gaps":[{"s":"Our AI runs on the ___, so the test data stays in the clinic.","a":"device","hint":"cihaz"},{"s":"In Europe, a law called GDPR ___ health data.","a":"protects","hint":"korur"},{"s":"We only use anonymous data from people who ___.","a":"agreed","hint":"onay verdi"}],"order":[{"a":"Patients need to know how we use their data."},{"a":"Our AI runs on the device."}],"translate":[{"tr":"Bizim için önce gizlilik gelir.","en":"Privacy comes first for us.","keys":["privacy","comes first"]},{"tr":"Araştırma için isimleri siliyoruz.","en":"We remove names for research.","keys":["remove names","research"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir gazeteci sağlık verileri ve gizlilik hakkında sorular soruyor. Net ve kısa cevaplar veriyorsun.","turns":[{"ai":"Who do you think owns a patient's health data?","aiTr":"Sizce bir hastanın sağlık verileri kime ait?","hint":"The patient owns it, because it is about their body and their life.","keys":["patient owns","their body","patient"]},{"ai":"Does your company send the test data to the cloud?","aiTr":"Şirketiniz test verilerini buluta gönderiyor mu?","hint":"No. Our AI runs on the device, so the data stays in the clinic.","keys":["runs on the device","stays in the clinic","no"]},{"ai":"But doesn't AI need a lot of data?","aiTr":"Ama yapay zekânın çok veriye ihtiyacı yok mu?","hint":"Yes, but we only use anonymous data from people who agreed. Privacy comes first.","keys":["anonymous","agreed","privacy comes first"]}]}},"in-03":{"intro":"Bir yatırım fonu teklif yaptı; sen değerleme üzerine pazarlık ediyorsun.","text":[{"who":"Investor","en":"We liked your pitch last week, so we want to make an offer.","tr":"Geçen haftaki sunumunuzu beğendik, bu yüzden bir teklif yapmak istiyoruz."},{"who":"Investor","en":"We can invest 500,000 euros for 25 percent of the company.","tr":"Şirketin yüzde 25'i karşılığında 500.000 euro yatırım yapabiliriz."},{"who":"Me","en":"Thank you, but that gives a valuation of only two million euros.","tr":"Teşekkürler ama bu sadece iki milyon euroluk bir değerleme demek."},{"who":"Me","en":"We think the company is worth more because we have paying customers.","tr":"Ödeme yapan müşterilerimiz olduğu için şirketin daha değerli olduğunu düşünüyoruz."},{"who":"Me","en":"Our product already works, and our clinical study was very successful.","tr":"Ürünümüz zaten çalışıyor ve klinik çalışmamız çok başarılı oldu."},{"who":"Investor","en":"Yes, but you don't have the CE mark yet, so the risk is higher.","tr":"Evet ama henüz CE işaretiniz yok, bu yüzden risk daha yüksek."},{"who":"Me","en":"I understand, so what about 2.5 million euros for 20 percent?","tr":"Anlıyorum, o zaman yüzde 20 için 2,5 milyon euroya ne dersiniz?"},{"who":"Investor","en":"That is OK for us, but we need a seat on the board.","tr":"Bu bizim için uygun ama yönetim kurulunda bir koltuğa ihtiyacımız var."},{"who":"Me","en":"No problem, because we want an active investor, not just money.","tr":"Sorun değil, çünkü sadece para değil, aktif bir yatırımcı istiyoruz."}],"vocab":[{"en":"make an offer","tr":"teklif yapmak","ex":"The fund wants to make an offer."},{"en":"valuation","tr":"değerleme","ex":"That gives a valuation of two million euros."},{"en":"be worth more","tr":"daha değerli olmak","ex":"We think the company is worth more."},{"en":"paying customer","tr":"ödeme yapan müşteri","ex":"We have five paying customers."},{"en":"clinical study","tr":"klinik çalışma","ex":"Our clinical study was very successful."},{"en":"the risk is higher","tr":"risk daha yüksek","ex":"Without the CE mark, the risk is higher."},{"en":"a seat on the board","tr":"yönetim kurulunda koltuk","ex":"They need a seat on the board."},{"en":"active investor","tr":"aktif yatırımcı","ex":"We want an active investor, not just money."}],"grammar":{"title":"Linking ideas: because, so, but","tr":"'because' bir sebep verir, 'so' bir sonuç verir, 'but' ise zıt bir fikir ekler. Pazarlıkta fikirlerini bağlamak için çok kullanışlıdır.","examples":["We liked your pitch, so we want to make an offer.","The company is worth more because we have paying customers.","That is OK for us, but we need a seat on the board."]},"questions":[{"q":"What was the first offer?","options":["500,000 euros for 20 percent","500,000 euros for 25 percent","2 million euros for 25 percent"],"a":1},{"q":"Why does the founder want a higher valuation?","options":["The team is very big","The office is new","They have paying customers and good study results"],"a":2},{"q":"Why does the investor think the risk is high?","options":["There is no CE mark yet","There are no customers","The price is too low"],"a":0},{"q":"What does the investor need at the end?","options":["More equity","A seat on the board","A lower price"],"a":1}],"gaps":[{"s":"We think the company is ___ more.","a":"worth","hint":"değerinde"},{"s":"That gives a ___ of only two million euros.","a":"valuation","hint":"değerleme"},{"s":"We need a ___ on the board.","a":"seat","hint":"koltuk"}],"order":[{"a":"We think the company is worth more because we have paying customers."},{"a":"We need a seat on the board."}],"translate":[{"tr":"Riski anlıyorum.","en":"I understand the risk.","keys":["understand","risk"]},{"tr":"Sadece para değil, aktif bir yatırımcı istiyoruz.","en":"We want an active investor, not just money.","keys":["active investor","not just money"]}],"roleplay":{"persona":"Venture capital investor","personaTr":"Risk sermayesi yatırımcısı","scene":"Bir VC fonu teklif yapıyor; değerleme üzerine pazarlık ediyorsun.","turns":[{"ai":"We can invest 500,000 euros for 25 percent of your company.","aiTr":"Şirketinizin yüzde 25'i için 500.000 euro yatırım yapabiliriz.","hint":"Thank you, but that is a valuation of only two million. We think we are worth more.","keys":["valuation","worth more","two million"]},{"ai":"Why do you think your company is worth more?","aiTr":"Şirketinizin neden daha değerli olduğunu düşünüyorsunuz?","hint":"Because we have paying customers and our clinical study was very successful.","keys":["paying customers","study","product"]},{"ai":"OK, 20 percent is possible, but we need a seat on the board.","aiTr":"Tamam, yüzde 20 olabilir ama yönetim kurulunda bir koltuğa ihtiyacımız var.","hint":"No problem, because we want an active investor, not just money.","keys":["no problem","active investor","board"]}]}}};
